class MetalCodegenError(NotImplementedError):
    """Raised when MSL codegen encounters an unsupported construct.

    Subclasses ``NotImplementedError`` so that callers can distinguish
    "incomplete backend" from genuine bugs and decide whether to fall back to
    CPU.
    """


# ---------------------------------------------------------------------------
# Type mapping
# ---------------------------------------------------------------------------


# C++ ctype string (as returned by ``Var.ctype()``) -> MSL type string.
# The values intentionally match Apple's MSL spec:
#   https://developer.apple.com/metal/Metal-Shading-Language-Specification.pdf
class _ScalarMslMap(dict):
    """``ctype -> MSL scalar`` map in which ``wp::float64`` resolves (to the
    emulated ``wp_f64``) only under ``warp.config.metal_fp64 = "emulate"``.

    Every other mode must keep seeing the key as *absent*: the ``"demote"``
    translators rewrite float64 tokens to float32 before they look anything
    up and rely on the miss for the paths they do not rewrite (e.g. the
    element scalar of a demoted array bound as ``ulong``), and ``"error"``
    relies on it to raise cleanly.
    """

    def __contains__(self, key) -> bool:
        if key == "wp::float64":
            return _fp64_mode() == "emulate"
        return dict.__contains__(self, key)

    def __getitem__(self, key):
        if key == "wp::float64" and _fp64_mode() != "emulate":
            raise KeyError(key)
        return dict.__getitem__(self, key)

    def get(self, key, default=None):
        return self[key] if key in self else default


_SCALAR_CTYPE_TO_MSL: dict[str, str] = _ScalarMslMap(
    {
        "wp::float16": "half",
        "wp::float32": "float",
        "wp::int32": "int",
        "wp::uint32": "uint",
        "wp::int64": "long",
        "wp::uint64": "ulong",
        "wp::int8": "char",
        "wp::uint8": "uchar",
        "wp::int16": "short",
        "wp::uint16": "ushort",
        # Emulated double (``metal_fp64 = "emulate"``): a POD struct around the
        # IEEE-754 bits, see ``_f64_emulate_helpers``. Present unconditionally so
        # type-name lookups resolve; the mode gates live in ``_msl_scalar_type``
        # / ``_msl_var_type`` and the array-argument check.
        "wp::float64": "wp_f64",
        # Bool is the one IR ctype without a ``wp::`` prefix — Warp emits plain
        # ``bool`` for boolean locals (e.g. the result of a comparison op).
        "wp::bool": "bool",
        "bool": "bool",
        # ``wp::slice_t`` is a 3-int struct (start, stop, step) used by
        # matrix slicing builtins (``mat[:, c]`` / ``mat[r, :]``). The MSL
        # equivalent ``wp_slice_t`` struct is emitted in the kernel header.
        "wp::slice_t": "wp_slice_t",
        # BVH traversal state — the MSL struct is emitted with ``_BVH_HELPERS``.
        "wp::bvh_query_t": "wp_bvh_query_t",
        "wp::mesh_query_aabb_t": "wp_mesh_query_aabb_t",
        # ``wp.mesh_get(id)`` locals hold the mesh descriptor itself (see
        # ``fold_mesh_get`` in ``codegen_metal_ast``).
        "wp::Mesh": "wp_mesh_desc_t",
        "wp::mesh_query_point_t": "wp_mesh_query_point_t",
        "wp::mesh_query_ray_t": "wp_mesh_query_ray_t",
        # Hash-grid traversal state (float32 grids only) — the MSL struct is
        # emitted with ``_HASHGRID_HELPERS``.
        "wp::hash_grid_query_f": "wp_hash_grid_query_t",
    }
)

# Builtin result structs whose fields kernels read directly (``q.result``,
# ``q.face``, ...). Locals of these ctypes are materialised as real MSL
# structs, so field-pointer lines alias to plain member access (see the
# ``builtin_struct_locals`` pass in ``_generate_kernel_body``).
_BUILTIN_FIELD_STRUCT_CTYPES = frozenset({"wp::mesh_query_point_t", "wp::mesh_query_ray_t"})

# MSL has built-in vector types ``floatN`` / ``intN`` / ``uintN`` etc. for
# N in {2, 3, 4}. Larger sizes (Warp's vec5, vec6, vec8) would need a custom
# struct, which we defer until they actually show up in a target kernel.
_MSL_VEC_SCALAR_PREFIX: dict[str, str] = _ScalarMslMap(
    {
        "wp::float16": "half",
        "wp::float32": "float",
        # Emulated double: never a native ``floatN`` — see ``_vec_native``.
        "wp::float64": "wp_f64",
        "wp::int32": "int",
        "wp::uint32": "uint",
        "wp::int16": "short",
        "wp::uint16": "ushort",
        "wp::int8": "char",
        "wp::uint8": "uchar",
        "wp::int64": "long",
        "wp::uint64": "ulong",
    }
)
_MSL_VEC_SUPPORTED_N = (2, 3, 4)

# The emulated double's MSL type name. Vectors / matrices of it have no
# native MSL counterpart (there is no ``wp_f642``), so every shape goes
# through the custom ``wp_vecN_wp_f64`` / ``wp_matRxC_wp_f64`` structs.
_F64_EMU_MSL = "wp_f64"


def _vec_native(n: int, msl_scalar: str) -> bool:
    """True when ``vec_t<n, scalar>`` lowers to a native MSL ``scalarN``."""
    return n in _MSL_VEC_NATIVE_N and msl_scalar != _F64_EMU_MSL


def _mat_native(rows: int, cols: int, msl_scalar: str) -> bool:
    """True when ``mat_t<rows, cols, scalar>`` lowers to a native MSL matrix
    (square 2-4; the emulated double always uses the row-major struct)."""
    return rows == cols and rows in _MSL_VEC_NATIVE_N and msl_scalar != _F64_EMU_MSL


# Pattern that matches ``wp::vec_t<N, wp::TYPE>`` — used both to translate
# variable ctypes (declarations) and constructor expressions inside the body.
_WP_VEC_T_PAT = re.compile(r"wp::vec_t\s*<\s*(\d+)\s*,\s*wp::(\w+)\s*>")
# Pattern that matches ``wp::mat_t<R, C, wp::TYPE>``.
_WP_MAT_T_PAT = re.compile(r"wp::mat_t\s*<\s*(\d+)\s*,\s*(\d+)\s*,\s*wp::(\w+)\s*>")
# Pattern that matches ``wp::quat_t<wp::TYPE>``. We treat quaternions as
# 4-element vec_t with float32 components — Warp lays them out the same
# way and our vec/mat machinery covers all the array, constructor, and
# extract patterns we currently see in mujoco_warp's hot path. Quat-
# specific operations (``wp.quat_inverse``, ``wp.quat_rotate``, etc.) would
# need their own translations later.
_WP_QUAT_T_PAT = re.compile(r"wp::quat_t\s*<\s*wp::(\w+)\s*>")
# ``wp::transform_t<wp::TYPE>`` — a rigid transform laid out as 7 scalars
# (px, py, pz, qx, qy, qz, qw). Normalized to ``vec_t<7>`` the same way
# quats become ``vec_t<4>``; the big-vec struct machinery then covers
# storage, constructors, and arithmetic, while the ``wp_transform_*``
# helpers cover the transform-specific operations.
_WP_TRANSFORM_T_PAT = re.compile(r"wp::transform_t\s*<\s*wp::(\w+)\s*>")


def _normalize_quat_t(text: str) -> str:
    """Rewrite quat/transform type references to their vec_t equivalents.

    ``wp::quat_t<wp::T>`` becomes ``wp::vec_t<4, wp::T>`` and
    ``wp::transform_t<wp::T>`` becomes ``wp::vec_t<7, wp::T>``. Run before
    any other vec/mat handling so the existing vec paths cover both
    seamlessly.
    """
    text = _WP_QUAT_T_PAT.sub(lambda m: f"wp::vec_t<4, wp::{m.group(1)}>", text)
    return _WP_TRANSFORM_T_PAT.sub(lambda m: f"wp::vec_t<7, wp::{m.group(1)}>", text)


_MSL_VEC_NATIVE_N = (2, 3, 4)

# MSL declares matrix types for floating-point element types only — there is
# no ``int2x2``. Integer matrices of every shape use our ``wp_mat*`` struct.
_MSL_NATIVE_MAT_SCALARS = ("float", "half")

# ``var_P = wp::indexref(var_V, idx);`` — component pointer into a vec
# lvalue (optionally through ``&``). Array-element forms are folded in the
# AST phase; this pattern feeds the vec-local alias pass in
# ``generate_msl_kernel``.
_INDEXREF_VEC_PAT = re.compile(
    r"^\s*var_(\w+)\s*=\s*wp::indexref\(\s*&?\(?\s*var_(\w+)\s*\)?\s*,\s*([^;]+?)\s*\)\s*;\s*$"
)


def _vec_ctype_len(ctype: str) -> int | None:
    """Component count if ``ctype`` is a vec/quat/transform value type (not
    a pointer), else ``None``."""
    stripped = ctype.strip()
    if stripped.endswith("*"):
        return None
    stripped = _normalize_quat_t(stripped)
    m = _WP_VEC_T_PAT.fullmatch(stripped)
    if m:
        return int(m.group(1))
    return None


def _msl_vec_name(n: int, msl_scalar: str) -> str:
    """Return the MSL type name for ``vec_t<N, T>`` given the MSL scalar prefix.

    Native ``floatN`` etc. for N in {2, 3, 4}; ``wp_vecN_<scalar>`` otherwise.
    """
    if _vec_native(n, msl_scalar):
        return f"{msl_scalar}{n}"
    return f"wp_vec{n}_{msl_scalar}"


def _msl_vec_ctor(n: int, msl_scalar: str) -> str:
    """Return the constructor / factory expression name for ``vec_t<N, T>``.

    For native sizes this matches the type name (``float3(a, b, c)``). For
    big sizes we use a free factory function ``wp_vecN_<scalar>_make`` —
    MSL doesn't let us declare a variadic struct constructor cleanly.
    """
    if _vec_native(n, msl_scalar):
        return f"{msl_scalar}{n}"
    return f"wp_vec{n}_{msl_scalar}_make"


def _vec_t_to_msl(n: int, scalar_ctype: str) -> str:
    """Translate ``wp::vec_t<N, wp::TYPE>`` to its MSL name.

    For N in {2, 3, 4} this returns the native MSL type (``floatN`` etc.).
    For larger N (vec5, vec6 = ``spatial_vector``, vec8) it returns a name
    like ``wp_vec6_float`` for which the codegen emits a custom struct
    declaration in the kernel header.
    """
    if n < 1:
        raise MetalCodegenError(f"MSL codegen: vec_t<{n}, ...> not supported")
    full_ctype = f"wp::{scalar_ctype}"
    # float64 VALUE locals: under ``"demote"`` they are fp32 vectors, the
    # same as bare ``wp::float64`` scalars (see ``_msl_var_type``); under
    # ``"emulate"`` they are ``wp_vecN_wp_f64`` structs for every N. Only
    # float64 *pointers* — i.e. array storage, whose 8-byte stride is
    # user-visible layout — are gated on the mode elsewhere.
    if full_ctype == "wp::float64" and _fp64_mode() != "emulate":
        full_ctype = "wp::float32"
    if full_ctype not in _MSL_VEC_SCALAR_PREFIX:
        raise MetalCodegenError(f"MSL codegen does not yet support vec_t element type {full_ctype!r}")
    msl_scalar = _MSL_VEC_SCALAR_PREFIX[full_ctype]
    if _vec_native(n, msl_scalar):
        return f"{msl_scalar}{n}"
    return f"wp_vec{n}_{msl_scalar}"


def _msl_mat_name(rows: int, cols: int, msl_scalar: str) -> str:
    """Return the MSL type name for ``mat_t<R, C, T>``.

    Native ``floatRxC`` only for *square* sizes — MSL's row-vs-column
    access semantics (``m[i]`` returns the i-th *MSL column*, which is
    Warp's "row i" only when the matrix is square — otherwise the
    shape doesn't even match). Non-square sizes route through our
    custom ``wp_mat{R}x{C}_<scalar>`` struct (row-major ``c[R*C]``)
    so reads and writes via ``m[i]`` go through the proxy that
    returns a Warp-row-shaped vector. Cartpole's ``mat_t<2, 3>``
    surfaced this — we now emit ``wp_mat2x3_float`` instead of MSL
    native ``float2x3``.

    Also floating-point only: MSL declares matrix types for ``float`` and
    ``half`` and nothing else, so an integer matrix of any shape uses the
    struct. (``int2x2`` is not a type — naming one is an ``unknown type
    name`` at MSL compile time.)

    This is THE rule for whether a matrix shape is native; callers that
    need the predicate should ask ``_is_native_mat_shape`` rather than
    re-deriving it.
    """
    if _mat_native(rows, cols, msl_scalar) and msl_scalar in _MSL_NATIVE_MAT_SCALARS:
        return f"{msl_scalar}{rows}x{cols}"
    return f"wp_mat{rows}x{cols}_{msl_scalar}"


def _mat_t_to_msl(rows: int, cols: int, scalar_ctype: str) -> str:
    """Translate ``wp::mat_t<R, C, wp::TYPE>`` to its MSL name.

    For sizes in {2, 3, 4} per dim this returns the native ``floatRxC``.
    For larger sizes it returns ``wp_matRxC_<scalar>`` for which the
    codegen emits a custom struct in the kernel header (alongside the
    big-vec structs).
    """
    if rows < 1 or cols < 1:
        raise MetalCodegenError(f"MSL codegen: mat_t<{rows}, {cols}, ...> not supported")
    full_ctype = f"wp::{scalar_ctype}"
    if full_ctype == "wp::float64" and _fp64_mode() != "emulate":
        full_ctype = "wp::float32"  # value locals demote — see ``_vec_t_to_msl``
    if full_ctype not in _MSL_VEC_SCALAR_PREFIX:
        raise MetalCodegenError(f"MSL codegen does not yet support mat_t element type {full_ctype!r}")
    return _msl_mat_name(rows, cols, _MSL_VEC_SCALAR_PREFIX[full_ctype])


def _translate_vec_t_in(text: str) -> str:
    """Replace every ``wp::vec_t<N, ...>`` and ``wp::mat_t<R, C, ...>`` reference
    in ``text`` with the MSL native type name (``float3``, ``float3x3``, etc.).
    Constructor calls are rewritten elsewhere (see ``_rewrite_mat_t_constructor``)
    because the row-major-to-column-major arg reorder differs from the simple
    name substitution this function does.
    """
    text = _WP_VEC_T_PAT.sub(lambda m: _vec_t_to_msl(int(m.group(1)), m.group(2)), text)
    text = _WP_MAT_T_PAT.sub(lambda m: _mat_t_to_msl(int(m.group(1)), int(m.group(2)), m.group(3)), text)
    return text


# ---------------------------------------------------------------------------
# Matrix constructor and storage layout
# ---------------------------------------------------------------------------
#
# MSL matrices are column-major: ``m[col][row]`` (so ``mat[0]`` is the first
# column as a vector). Warp stores matrices row-major in array buffers and
# the IR's ``wp::mat_t<R, C, T>(v00, v01, v02, v10, ...)`` constructor takes
# row-major flat args.
#
# Convention: keep the *logical* matrix the same on both sides. MSL column
# ``k`` corresponds to logical column ``k``. So ``m * v``, ``m1 * m2``, and
# ``transpose(m)`` all work with native MSL operators. The trade-off:
#  - The constructor must reorder row-major args into column form
#    (handled by ``_rewrite_mat_t_constructor``).
#  - ``wp::extract(m, i, j)`` (row i, col j) becomes ``m[j][i]`` in MSL.
#  - Reads from row-major array storage build columns by gathering strided
#    elements; writes scatter back the same way (handled in
#    ``generate_msl_kernel`` alongside vec arrays).


# ---------------------------------------------------------------------------
# Custom big-vec struct emission (vec5, vec6 = spatial_vector, vec8, ...)
# ---------------------------------------------------------------------------
#
# MSL has no native ``floatN`` for N > 4. We emit a small custom struct per
# ``(N, scalar)`` combination used by the kernel, with operator overloads so
# the existing ``wp::add(a, b) -> (a + b)`` translations Just Work for the
# resulting MSL types.
# Match ``wp_vec<N>_<scalar>`` (struct type or factory call). The
# scalar set is enumerated to anchor the match — a lazy ``(\w+)``
# would greedily pick up ``float_make`` from ``wp_vec6_float_make``,
# classifying the scalar as "float_make" and missing the struct
# emission. The optional ``_make`` suffix lets the same regex match
# both the bare struct name and the factory call.
_BIG_VEC_NAME_PAT = re.compile(
    r"\bwp_vec(\d+)_(wp_f64|half|float|double|int|uint|long|ulong|char|uchar|short|ushort|bool)"
    r"(?:_make)?\b"
)
# Stripped scalar -> MSL scalar prefix lookup. Goes from "float" / "int" etc.
# back to the same name (it's a no-op convenience map for clarity).
_MSL_PREFIX_TO_SAME = {prefix: prefix for prefix in _MSL_VEC_SCALAR_PREFIX.values()}


def _emit_big_vec_struct(name: str, n: int, msl_scalar: str) -> str:
    """Emit the MSL declaration for a custom big-vec struct.

    The struct has a plain N-element scalar array as its only data member,
    plus operator overloads (+, -, * by scalar, /, [] for read+write, ==).
    Each unrolled component-wise operation is generated explicitly so the
    MSL compiler can vectorise without trusting an MSL ``for`` loop with a
    runtime bound.
    """
    body_lines: list[str] = []
    body_lines.append(f"struct {name} {{")
    body_lines.append(f"    {msl_scalar} c[{n}];")
    body_lines.append(f"    inline thread {msl_scalar}& operator[](int i) thread {{ return c[i]; }}")
    body_lines.append(f"    inline {msl_scalar} operator[](int i) const thread {{ return c[i]; }}")
    if msl_scalar == _F64_EMU_MSL and n in _MSL_VEC_NATIVE_N:
        # ``wp.vec2f(v_f64)`` lowers to the functional cast ``float2(v)``,
        # which MSL only accepts through a conversion operator.
        for nat in ("float", "half", "int", "uint"):
            comps = ", ".join(f"{nat}(c[{i}])" for i in range(n))
            body_lines.append(f"    inline explicit operator {nat}{n}() const thread {{ return {nat}{n}({comps}); }}")
    body_lines.append("};")
    # Variadic-arg constructor: ``wp_vec6_float(v0, v1, ..., v5)`` so the
    # existing IR ``wp::vec_t<6, ...>(...)`` (with the braces stripped) maps
    # directly. We can't define a templated constructor on the struct in a
    # forward-portable way, so emit a free factory function with the same
    # name as the type — MSL allows ``wp_vec6_float(args...)`` to dispatch
    # to a function of that name when no constructor matches.
    args = ", ".join(f"{msl_scalar} v{i}" for i in range(n))
    body_lines.append(f"inline {name} {name}_make({args}) {{")
    body_lines.append(f"    {name} r;")
    for i in range(n):
        body_lines.append(f"    r.c[{i}] = v{i};")
    body_lines.append("    return r;")
    body_lines.append("}")
    # Single-scalar broadcast overload: Warp's IR emits
    # ``wp_vecN_<scalar>_make(scalar)`` for ``vec_t<N>(s)`` patterns
    # (e.g. ``wp.vec8(0.0)`` to zero-init or fill). For n == 1 this is
    # the same signature as the per-component factory above — skip it.
    if n > 1:
        body_lines.append(f"inline {name} {name}_make({msl_scalar} v) {{")
        body_lines.append(f"    {name} r;")
        for i in range(n):
            body_lines.append(f"    r.c[{i}] = v;")
        body_lines.append("    return r;")
        body_lines.append("}")
    # Copy overload: ``vec_t<N>(v)`` with a same-type operand (Warp's
    # explicit copy-construction, e.g. warp.fem's vec1 accumulators).
    body_lines.append(f"inline {name} {name}_make({name} v) {{ return v; }}")
    # ``wp.transform(p, q)``: transform_t is normalized to ``vec_t<7>`` (see
    # ``_normalize_quat_t``), so its (position, rotation) constructor
    # reaches here as ``wp_vec7_<scalar>_make(vec3, quat)``.
    if n == 7 and msl_scalar in _MSL_NATIVE_MAT_SCALARS:
        body_lines.append(
            f"inline {name} {name}_make({msl_scalar}3 p, {msl_scalar}4 q) {{ "
            f"return {name}_make(p.x, p.y, p.z, q.x, q.y, q.z, q.w); }}"
        )
    # Emulated double <-> native vector conversions (``wp.vec2d(v_f32)`` and
    # ``wp.vec2f(v_f64)``): the native ``floatN`` types always exist, so the
    # overloads can be emitted unconditionally for N in 2..4.
    if msl_scalar == _F64_EMU_MSL and n in _MSL_VEC_NATIVE_N:
        for nat in ("float", "half", "int", "uint"):
            comps = ", ".join(f"wp_f64_from(v[{i}])" for i in range(n))
            body_lines.append(f"inline {name} {name}_make({nat}{n} v) {{ return {name}_make({comps}); }}")
    # Operator overloads. Component-wise unrolled for clarity and so MSL's
    # auto-vectoriser sees independent statements.
    for op in ("+", "-", "*", "/"):
        body_lines.append(f"inline {name} operator{op}({name} a, {name} b) {{")
        body_lines.append(f"    {name} r;")
        for i in range(n):
            body_lines.append(f"    r.c[{i}] = a.c[{i}] {op} b.c[{i}];")
        body_lines.append("    return r;")
        body_lines.append("}")
    # Scalar operators. Warp lowers ``vec * scalar`` and ``scalar * vec``
    # (and the equivalents for ``+``, ``-``, ``/``) to plain ``*``/``/``
    # binary expressions, so MSL needs both orderings. Without these,
    # kernels like ``cdof[dofid] * qvel[dofid]`` (spatial-vector ``*`` joint
    # velocity) fail to compile.
    for op in ("+", "-", "*", "/"):
        body_lines.append(f"inline {name} operator{op}({name} a, {msl_scalar} s) {{")
        body_lines.append(f"    {name} r;")
        for i in range(n):
            body_lines.append(f"    r.c[{i}] = a.c[{i}] {op} s;")
        body_lines.append("    return r;")
        body_lines.append("}")
        body_lines.append(f"inline {name} operator{op}({msl_scalar} s, {name} a) {{")
        body_lines.append(f"    {name} r;")
        for i in range(n):
            body_lines.append(f"    r.c[{i}] = s {op} a.c[{i}];")
        body_lines.append("    return r;")
        body_lines.append("}")
    # Compound assignment. Defining ``operator+`` does NOT give C++ (or
    # MSL) ``operator+=``, and the generic reverse-mode templates in
    # ``_ADJ_HELPERS`` accumulate with ``+=`` / ``-=`` on whatever type
    # they deduce — ``wp_adj_add``, ``wp_adj_sub``, ``wp_adj_where``,
    # ``wp_adj_mul``, ``wp_adj_div``. Without these, differentiating any
    # kernel that carries a big-vec value (warp.fem's ``vec1`` scalar-space
    # dofs, spatial vectors) fails with "no viable overloaded '+='".
    for op in ("+", "-", "*", "/"):
        body_lines.append(f"inline thread {name}& operator{op}=(thread {name}& a, {name} b) {{")
        for i in range(n):
            body_lines.append(f"    a.c[{i}] {op}= b.c[{i}];")
        body_lines.append("    return a;")
        body_lines.append("}")
        body_lines.append(f"inline thread {name}& operator{op}=(thread {name}& a, {msl_scalar} s) {{")
        for i in range(n):
            body_lines.append(f"    a.c[{i}] {op}= s;")
        body_lines.append("    return a;")
        body_lines.append("}")
    # Unary minus: ``-spatial_vec``. The IR lowers ``wp.neg(v)`` to
    # ``-v`` for native vec types but for our big-vec structs the codegen
    # path still funnels through ``wp_neg`` (see ``_INTRINSIC_PATTERNS``).
    # Provide both forms so either lowering compiles.
    body_lines.append(f"inline {name} operator-({name} a) {{")
    body_lines.append(f"    {name} r;")
    for i in range(n):
        body_lines.append(f"    r.c[{i}] = -a.c[{i}];")
    body_lines.append("    return r;")
    body_lines.append("}")
    # Equality / inequality: ``vec == zero`` shows up in actuator gating
    # paths (e.g. ``_apply_ft`` checks whether a force-torque pair is the
    # zero spatial vector). Component-wise compare; results AND/OR'd.
    body_lines.append(f"inline bool operator==({name} a, {name} b) {{")
    body_lines.append("    return " + " && ".join(f"a.c[{i}] == b.c[{i}]" for i in range(n)) + ";")
    body_lines.append("}")
    body_lines.append(f"inline bool operator!=({name} a, {name} b) {{")
    body_lines.append("    return !(a == b);")
    body_lines.append("}")

    # Unary ``wp.min(v)`` / ``wp.max(v)`` and ``wp.argmin(v)`` /
    # ``wp.argmax(v)``; the native-width forms live in
    # ``_MISC_MATH_HELPERS``. argmin/argmax skip NaN slots like
    # warp/native/vec.h.
    def nan_chk(e: str) -> str:
        return f"metal::isnan(float({e}))" if msl_scalar in ("float", "half") else "false"

    for fn, cmp in (("min", "<"), ("max", ">")):
        # Fold like warp/native/vec.h: ``fmin``/``fmax`` (NaN-ignoring) for
        # floating point, ``a < b ? a : b`` otherwise.
        if msl_scalar in ("float", "half"):
            step = f"r = metal::f{fn}(r, v.c[i]);"
        else:
            step = f"r = (r {cmp} v.c[i]) ? r : v.c[i];"
        body_lines.append(f"inline {msl_scalar} wp_v{fn}({name} v) {{")
        body_lines.append(f"    {msl_scalar} r = v.c[0];")
        body_lines.append(f"    for (int i = 1; i < {n}; ++i) {step}")
        body_lines.append("    return r;")
        body_lines.append("}")
        body_lines.append(f"inline uint wp_arg{fn}({name} v) {{")
        body_lines.append("    uint ret = 0;")
        body_lines.append(f"    while (ret < {n}u && {nan_chk('v.c[ret]')}) ++ret;")
        body_lines.append(f"    if (ret == {n}u) return 0u;")
        body_lines.append(f"    for (uint i = ret + 1; i < {n}u; ++i) {{")
        body_lines.append(f"        if ({nan_chk('v.c[i]')}) continue;")
        body_lines.append(f"        if (v.c[i] {cmp} v.c[ret]) ret = i;")
        body_lines.append("    }")
        body_lines.append("    return ret;")
        body_lines.append("}")
    for fn in ("min", "max"):
        body_lines.append(
            f"inline void wp_adj_{fn}({name} v, thread {name}& av, {msl_scalar} r) {{ av.c[wp_arg{fn}(v)] += r; }}"
        )
    body_lines.append("template <typename V, typename S>")
    body_lines.append(
        f"inline void wp_vec_slice_store(thread {name}& d, S s, V v) "
        "{ int k = 0; for (int i = s.start; (s.step > 0) ? (i < s.stop) : (i > s.stop); i += s.step) d.c[i] = v[k++]; }"
    )
    body_lines.append("template <typename D, typename S>")
    body_lines.append(
        f"inline void wp_vec_slice_assign(thread D& d, {name} v, S s) "
        "{ int k = 0; for (int i = s.start; (s.step > 0) ? (i < s.stop) : (i > s.stop); i += s.step) d[k++] = v.c[i]; }"
    )
    # ``wp.length`` / ``wp.normalize`` — ``metal::length`` only knows the
    # native vector widths. warp.fem's scalar function spaces make ``vec1``
    # dof values, so even n == 1 reaches these.
    sum_sq = " + ".join(f"v.c[{i}] * v.c[{i}]" for i in range(n))
    body_lines.append(f"inline {msl_scalar} wp_length({name} v) {{")
    if msl_scalar == _F64_EMU_MSL:
        body_lines.append(f"    return metal::sqrt({sum_sq});")
    else:
        body_lines.append(f"    return ({msl_scalar})metal::precise::sqrt(float({sum_sq}));")
    body_lines.append("}")
    body_lines.append(f"inline {name} wp_normalize({name} v) {{")
    body_lines.append(f"    {msl_scalar} l = wp_length(v);")
    body_lines.append(f"    {name} r;")
    _zero = _sc_zero(msl_scalar)
    body_lines.append(f"    for (int i = 0; i < {n}; ++i) r.c[i] = (l > {_zero}) ? (v.c[i] / l) : {_zero};")
    body_lines.append("    return r;")
    body_lines.append("}")
    # Reverse-mode overloads for this struct shape. The generic templates in
    # ``_ADJ_HELPERS`` (``wp_adj_add``, ``wp_adj_where``, ...) already work
    # off the compound-assignment operators above, but the constructor and
    # element-extract adjoints are shape-specific and have no template form,
    # so emit them per struct rather than hand-listing widths. Unused
    # overloads are inline and cost nothing.
    ctor_args = ", ".join(f"{msl_scalar} c{i}" for i in range(n))
    ctor_refs = ", ".join(f"thread {msl_scalar}& a{i}" for i in range(n))
    body_lines.append(f"inline void wp_adj_vec_t({ctor_args}, {ctor_refs}, {name} r) {{")
    for i in range(n):
        body_lines.append(f"    a{i} += r.c[{i}];")
    body_lines.append("}")
    # One-scalar form broadcasts, so its adjoint sums the whole gradient.
    # At n == 1 that signature is identical to the per-component form above,
    # and emitting both is a redefinition.
    if n > 1:
        bcast_sum = " + ".join(f"r.c[{i}]" for i in range(n))
        body_lines.append(
            f"inline void wp_adj_vec_t({msl_scalar} c, thread {msl_scalar}& a, {name} r) {{ a += {bcast_sum}; }}"
        )
    # Copy / element-cast constructor.
    body_lines.append(f"inline void wp_adj_vec_t({name} other, thread {name}& ao, {name} r) {{ ao += r; }}")
    if msl_scalar == _F64_EMU_MSL and n in _MSL_VEC_NATIVE_N:
        # Adjoints of the two conversion constructors (``vec2d(v_f32)`` and
        # ``vec2f(v_f64)``): the gradient converts back the other way. Emitted
        # here, after the struct's ``operator+=`` exists.
        for nat in ("float", "half"):
            body_lines.append(
                f"inline void wp_adj_vec_t({nat}{n} other, thread {nat}{n}& ao, {name} r) {{ ao += {nat}{n}(r); }}"
            )
            body_lines.append(
                f"inline void wp_adj_vec_t({name} other, thread {name}& ao, {nat}{n} r) {{ ao += {name}_make(r); }}"
            )
    # ``wp.extract(v, i)`` — scatter the scalar adjoint into component i.
    # The index is non-differentiable but Warp still names its dual.
    body_lines.append(
        f"inline void wp_adj_extract({name} v, int i, thread {name}& av, thread int& ai, {msl_scalar} r) "
        f"{{ av.c[i] += r; }}"
    )
    # Scalar scale / divide. The generic ``wp_adj_mul`` template deduces a
    # single ``T`` for both operands, so a struct-by-scalar product has no
    # candidate without these.
    body_lines.append(
        f"inline void wp_adj_mul({name} a, {msl_scalar} b, thread {name}& aa, thread {msl_scalar}& ab, {name} r) {{"
    )
    body_lines.append("    aa += r * b;")
    body_lines.append(f"    for (int i = 0; i < {n}; ++i) ab += a.c[i] * r.c[i];")
    body_lines.append("}")
    body_lines.append(
        f"inline void wp_adj_mul({msl_scalar} a, {name} b, thread {msl_scalar}& aa, thread {name}& ab, {name} r) {{"
    )
    body_lines.append("    ab += r * a;")
    body_lines.append(f"    for (int i = 0; i < {n}; ++i) aa += b.c[i] * r.c[i];")
    body_lines.append("}")
    body_lines.append(
        f"inline void wp_adj_div({name} a, {msl_scalar} b, {name} ret, thread {name}& aa, "
        f"thread {msl_scalar}& ab, {name} r) {{"
    )
    body_lines.append("    aa += r / b;")
    body_lines.append(f"    for (int i = 0; i < {n}; ++i) ab -= r.c[i] * ret.c[i] / b;")
    body_lines.append("}")
    # 5-arg forms (no ``ret``) for vec/scalar and scalar/vec division.
    body_lines.append(
        f"inline void wp_adj_div({name} a, {msl_scalar} s, thread {name}& aa, thread {msl_scalar}& as, {name} r) {{"
    )
    body_lines.append(f"    {msl_scalar} d = {_sc_zero(msl_scalar)};")
    body_lines.append(f"    for (int i = 0; i < {n}; ++i) d += a.c[i] * r.c[i];")
    body_lines.append("    as -= d / (s * s);")
    body_lines.append(f"    for (int i = 0; i < {n}; ++i) aa.c[i] += r.c[i] / s;")
    body_lines.append("}")
    body_lines.append(
        f"inline void wp_adj_div({msl_scalar} s, {name} a, thread {msl_scalar}& as, thread {name}& aa, {name} r) {{"
    )
    body_lines.append(
        f"    for (int i = 0; i < {n}; ++i) {{ {msl_scalar} inv = {_sc_lit(msl_scalar, 1)} / a.c[i]; "
        f"aa.c[i] -= s * r.c[i] * inv * inv; as += r.c[i] * inv; }}"
    )
    body_lines.append("}")
    # dot / length / length_sq / normalize, mirroring ``_adj_vec_helpers``
    # for the native widths.
    body_lines.append(
        f"inline void wp_adj_dot({name} a, {name} b, thread {name}& aa, thread {name}& ab, {msl_scalar} r) {{"
    )
    body_lines.append(f"    for (int i = 0; i < {n}; ++i) {{ aa.c[i] += b.c[i] * r; ab.c[i] += a.c[i] * r; }}")
    body_lines.append("}")
    body_lines.append(f"inline void wp_adj_length({name} a, {msl_scalar} ret, thread {name}& aa, {msl_scalar} r) {{")
    body_lines.append(
        f"    if (ret > {_sc_zero(msl_scalar)}) for (int i = 0; i < {n}; ++i) aa.c[i] += a.c[i] * (r / ret);"
    )
    body_lines.append("}")
    body_lines.append(f"inline void wp_adj_length_sq({name} a, thread {name}& aa, {msl_scalar} r) {{")
    body_lines.append(f"    for (int i = 0; i < {n}; ++i) aa.c[i] += a.c[i] * ({_sc_lit(msl_scalar, 2)} * r);")
    body_lines.append("}")
    body_lines.append(f"inline void wp_adj_normalize({name} a, {name} ret, thread {name}& aa, {name} r) {{")
    body_lines.append(f"    {msl_scalar} d = wp_length(a);")
    body_lines.append(f"    if (d <= {_sc_zero(msl_scalar)}) return;")
    body_lines.append(f"    {msl_scalar} rd = {_sc_zero(msl_scalar)};")
    body_lines.append(f"    for (int i = 0; i < {n}; ++i) rd += ret.c[i] * r.c[i];")
    body_lines.append(f"    for (int i = 0; i < {n}; ++i) aa.c[i] += (r.c[i] - ret.c[i] * rd) / d;")
    body_lines.append("}")
    # Component-wise products.
    body_lines.append(
        f"inline void wp_adj_cw_mul({name} a, {name} b, thread {name}& aa, thread {name}& ab, {name} r) {{"
    )
    body_lines.append(
        f"    for (int i = 0; i < {n}; ++i) {{ aa.c[i] += b.c[i] * r.c[i]; ab.c[i] += a.c[i] * r.c[i]; }}"
    )
    body_lines.append("}")
    body_lines.append(
        f"inline void wp_adj_cw_div({name} a, {name} b, {name} ret, thread {name}& aa, thread {name}& ab, {name} r) {{"
    )
    body_lines.append(
        f"    for (int i = 0; i < {n}; ++i) {{ aa.c[i] += r.c[i] / b.c[i]; ab.c[i] -= r.c[i] * ret.c[i] / b.c[i]; }}"
    )
    body_lines.append("}")
    return "\n".join(body_lines)


def _emit_spatial_helpers() -> str:
    """Helpers specific to ``spatial_vector`` (``vec_t<6, float32>``).

    - ``wp_spatial_top`` / ``wp_spatial_bottom`` decompose into the upper /
      lower vec3.
    - A ``(float3, float3)`` overload of ``wp_vec6_float_make`` mirrors
      Warp's ``wp.spatial_vector(top_vec3, bottom_vec3)`` two-arg
      constructor (used wherever a kernel composes a spatial_vector from
      two vec3s rather than 6 scalars).
    - ``wp_spatial_cross`` / ``wp_spatial_cross_dual`` port
      warp/native/spatial.h (top = angular ``w``, bottom = linear ``v``).
      ``spatial_dot`` needs no helper — it rewrites to ``wp_dot``.
    """
    return (
        "inline float3 wp_spatial_top(wp_vec6_float v) { "
        "return float3(v.c[0], v.c[1], v.c[2]); }\n"
        "inline float3 wp_spatial_bottom(wp_vec6_float v) { "
        "return float3(v.c[3], v.c[4], v.c[5]); }\n"
        "inline wp_vec6_float wp_vec6_float_make(float3 a, float3 b) { "
        "return wp_vec6_float_make(a[0], a[1], a[2], b[0], b[1], b[2]); }\n"
        "inline wp_vec6_float wp_spatial_cross(wp_vec6_float a, wp_vec6_float b) {\n"
        "    float3 aw = wp_spatial_top(a); float3 av = wp_spatial_bottom(a);\n"
        "    float3 bw = wp_spatial_top(b); float3 bv = wp_spatial_bottom(b);\n"
        "    float3 w = metal::cross(aw, bw);\n"
        "    float3 v = metal::cross(av, bw) + metal::cross(aw, bv);\n"
        "    return wp_vec6_float_make(w, v);\n"
        "}\n"
        "inline wp_vec6_float wp_spatial_cross_dual(wp_vec6_float a, wp_vec6_float b) {\n"
        "    float3 aw = wp_spatial_top(a); float3 av = wp_spatial_bottom(a);\n"
        "    float3 bw = wp_spatial_top(b); float3 bv = wp_spatial_bottom(b);\n"
        "    float3 w = metal::cross(aw, bw) + metal::cross(av, bv);\n"
        "    float3 v = metal::cross(aw, bv);\n"
        "    return wp_vec6_float_make(w, v);\n"
        "}\n"
        # Reverse-mode counterparts (warp/native/spatial.h). ``adj_cross(a, b,
        # aa, ab, r)`` accumulates ``aa += b x r`` and ``ab += r x a``.
        "inline void wp_adj_spatial_top(wp_vec6_float a, thread wp_vec6_float& aa, float3 r) {\n"
        "    aa.c[0] += r.x; aa.c[1] += r.y; aa.c[2] += r.z;\n"
        "}\n"
        "inline void wp_adj_spatial_bottom(wp_vec6_float a, thread wp_vec6_float& aa, float3 r) {\n"
        "    aa.c[3] += r.x; aa.c[4] += r.y; aa.c[5] += r.z;\n"
        "}\n"
        "inline void wp_adj_vec_t(float3 a, float3 b, thread float3& aa, thread float3& ab, wp_vec6_float r) {\n"
        "    aa += wp_spatial_top(r); ab += wp_spatial_bottom(r);\n"
        "}\n"
        "inline void wp_adj_spatial_dot(wp_vec6_float a, wp_vec6_float b, thread wp_vec6_float& aa, "
        "thread wp_vec6_float& ab, float r) {\n"
        "    wp_adj_dot(a, b, aa, ab, r);\n"
        "}\n"
        "inline void wp_adj_spatial_cross_impl(float3 a, float3 b, thread float3& aa, thread float3& ab, float3 r) {\n"
        "    aa += metal::cross(b, r); ab += metal::cross(r, a);\n"
        "}\n"
        "inline void wp_adj_spatial_cross(wp_vec6_float a, wp_vec6_float b, thread wp_vec6_float& aa, "
        "thread wp_vec6_float& ab, wp_vec6_float r) {\n"
        "    float3 aw = wp_spatial_top(a), av = wp_spatial_bottom(a);\n"
        "    float3 bw = wp_spatial_top(b), bv = wp_spatial_bottom(b);\n"
        "    float3 rw = wp_spatial_top(r), rv = wp_spatial_bottom(r);\n"
        "    float3 aaw = float3(0.0f), aav = float3(0.0f), abw = float3(0.0f), abv = float3(0.0f);\n"
        "    wp_adj_spatial_cross_impl(aw, bw, aaw, abw, rw);\n"
        "    wp_adj_spatial_cross_impl(av, bw, aav, abw, rv);\n"
        "    wp_adj_spatial_cross_impl(aw, bv, aaw, abv, rv);\n"
        "    aa += wp_vec6_float_make(aaw, aav); ab += wp_vec6_float_make(abw, abv);\n"
        "}\n"
        "inline void wp_adj_spatial_cross_dual(wp_vec6_float a, wp_vec6_float b, thread wp_vec6_float& aa, "
        "thread wp_vec6_float& ab, wp_vec6_float r) {\n"
        "    float3 aw = wp_spatial_top(a), av = wp_spatial_bottom(a);\n"
        "    float3 bw = wp_spatial_top(b), bv = wp_spatial_bottom(b);\n"
        "    float3 rw = wp_spatial_top(r), rv = wp_spatial_bottom(r);\n"
        "    float3 aaw = float3(0.0f), aav = float3(0.0f), abw = float3(0.0f), abv = float3(0.0f);\n"
        "    wp_adj_spatial_cross_impl(aw, bw, aaw, abw, rw);\n"
        "    wp_adj_spatial_cross_impl(av, bv, aav, abv, rw);\n"
        "    wp_adj_spatial_cross_impl(aw, bv, aaw, abv, rv);\n"
        "    aa += wp_vec6_float_make(aaw, aav); ab += wp_vec6_float_make(abw, abv);\n"
        "}"
    )


_BIG_MAT_NAME_PAT = re.compile(r"\bwp_mat(\d+)x(\d+)_(\w+)\b")


def _emit_f64_square_mat_helpers(name: str, n: int) -> str:
    """``metal::determinant`` / ``wp_trace`` / ``wp_inverse`` overloads for a
    square emulated-double matrix struct (the native ``floatNxN`` versions
    come from MSL and ``_MISC_MATH_HELPERS``). Row-major ``c[r * n + c]``."""

    def e(r: int, c: int) -> str:
        return f"m.c[{r * n + c}]"

    L: list[str] = []
    if n == 1:
        det = e(0, 0)
    elif n == 2:
        det = f"({e(0, 0)} * {e(1, 1)} - {e(0, 1)} * {e(1, 0)})"
    elif n == 3:
        det = (
            f"({e(0, 0)} * ({e(1, 1)} * {e(2, 2)} - {e(1, 2)} * {e(2, 1)}) "
            f"- {e(0, 1)} * ({e(1, 0)} * {e(2, 2)} - {e(1, 2)} * {e(2, 0)}) "
            f"+ {e(0, 2)} * ({e(1, 0)} * {e(2, 1)} - {e(1, 1)} * {e(2, 0)}))"
        )
    else:
        # Laplace expansion along the first row over 3x3 minors.
        def minor3(skip_c: int) -> str:
            cols = [c for c in range(4) if c != skip_c]
            a = [[f"m.c[{r * 4 + c}]" for c in cols] for r in (1, 2, 3)]
            return (
                f"({a[0][0]} * ({a[1][1]} * {a[2][2]} - {a[1][2]} * {a[2][1]}) "
                f"- {a[0][1]} * ({a[1][0]} * {a[2][2]} - {a[1][2]} * {a[2][0]}) "
                f"+ {a[0][2]} * ({a[1][0]} * {a[2][1]} - {a[1][1]} * {a[2][0]}))"
            )

        det = " ".join(f"{'+' if c % 2 == 0 else '-'} {e(0, c)} * {minor3(c)}" for c in range(4)).lstrip("+ ")
        det = f"({det})"
    L.append(f"namespace metal {{ inline wp_f64 determinant({name} m) {{ return {det}; }} }}")
    trace = " + ".join(e(i, i) for i in range(n))
    L.append(f"inline wp_f64 wp_trace({name} m) {{ return {trace}; }}")
    if n == 1:
        L.append(
            f"inline {name} wp_inverse({name} m) {{ {name} r; r.c[0] = wp_f64{{0x3ff0000000000000UL}} / m.c[0]; return r; }}"
        )
    elif n == 2:
        L.append(f"inline {name} wp_inverse({name} m) {{")
        L.append("    wp_f64 inv = wp_f64{0x3ff0000000000000UL} / metal::determinant(m);")
        L.append(f"    {name} r;")
        L.append(
            f"    r.c[0] = {e(1, 1)} * inv; r.c[1] = -{e(0, 1)} * inv; r.c[2] = -{e(1, 0)} * inv; r.c[3] = {e(0, 0)} * inv;"
        )
        L.append("    return r;")
        L.append("}")
    elif n == 3:
        L.append(f"inline {name} wp_inverse({name} m) {{")
        L.append("    wp_f64 inv = wp_f64{0x3ff0000000000000UL} / metal::determinant(m);")
        L.append(f"    {name} r;")
        for r in range(3):
            for c in range(3):
                # cofactor C(c, r) / det  (adjugate is the transposed cofactor matrix)
                rr = [i for i in range(3) if i != c]
                cc = [j for j in range(3) if j != r]
                cof = f"({e(rr[0], cc[0])} * {e(rr[1], cc[1])} - {e(rr[0], cc[1])} * {e(rr[1], cc[0])})"
                sign = "" if (r + c) % 2 == 0 else "-"
                L.append(f"    r.c[{r * 3 + c}] = {sign}{cof} * inv;")
        L.append("    return r;")
        L.append("}")
    return "\n".join(L)


def _emit_big_mat_struct(name: str, rows: int, cols: int, msl_scalar: str) -> str:
    """Emit the MSL declaration for a custom big-mat struct.

    Storage is row-major (matches Warp's IR semantics directly) — element
    ``(r, c)`` lives at ``c[r * cols + c]``. Exposes:
      * Flat row-major ``_make`` factory.
      * ``operator[](int)`` for both read (returns a row vector by value)
        and write (returns a small proxy that overloads ``= vec`` to
        dispatch to per-element stores). Cartpole's narrowphase uses
        ``mat[i] = vec3`` (set row) and ``vec3 v = mat[i]`` (get row);
        the proxy resolves both.
      * ``_extract`` helper for ``wp::extract(m, r, c)``.
      * Arithmetic: ``+``/``-``/scalar ``*``/``/``, ``mat * vec`` /
        ``vec * mat``, and (square only) ``mat * mat`` — enough for
        spatial-matrix algebra (``wp.spatial_matrix`` products).
    """
    n = rows * cols
    # Row-vector type. Native ``floatN`` / ``intN`` for cols in 2..4 and
    # supported scalars; otherwise the custom ``wp_vecN_<scalar>`` struct.
    if _vec_native(cols, msl_scalar) and msl_scalar in _MSL_PREFIX_TO_SAME:
        row_type = f"{msl_scalar}{cols}"
        row_make = f"{row_type}(" + ", ".join(f"c[i*{cols}+{j}]" for j in range(cols)) + ")"
        proxy_assign = "; ".join(f"p[{j}] = v[{j}]" for j in range(cols))
        proxy_read = f"{row_type}(" + ", ".join(f"p[{j}]" for j in range(cols)) + ")"
    else:
        row_type = f"wp_vec{cols}_{msl_scalar}"
        row_make = f"{row_type}{{" + ", ".join(f"c[i*{cols}+{j}]" for j in range(cols)) + "}"
        proxy_assign = "; ".join(f"p[{j}] = v.c[{j}]" for j in range(cols))
        proxy_read = f"{row_type}{{" + ", ".join(f"p[{j}]" for j in range(cols)) + "}"
    proxy = f"{name}_row_ref"
    body: list[str] = []
    # Forward-declare the proxy so the struct's non-const operator[]
    # signature can name it before the proxy body is emitted.
    body.append(f"struct {proxy};")
    body.append(f"struct {name} {{")
    body.append(f"    {msl_scalar} c[{n}];")
    body.append(f"    inline {row_type} operator[](int i) const thread {{ return {row_make}; }}")
    body.append(f"    inline {proxy} operator[](int i) thread;")
    body.append("};")
    body.append(f"struct {proxy} {{")
    body.append(f"    thread {msl_scalar}* p;")
    # Element subscript so ``m[r][c]`` reads/writes work through the proxy
    # (the matrix array-store epilogue and chained subscripts rely on it).
    body.append(f"    inline {msl_scalar} operator[](int j) const thread {{ return p[j]; }}")
    body.append(f"    inline thread {msl_scalar}& operator[](int j) thread {{ return p[j]; }}")
    body.append(f"    inline operator {row_type}() const thread {{ return {proxy_read}; }}")
    body.append(f"    inline thread {proxy}& operator=({row_type} v) thread {{")
    body.append(f"        {proxy_assign};")
    body.append("        return *this;")
    body.append("    }")
    body.append("};")
    body.append(f"inline {proxy} {name}::operator[](int i) thread {{ return {proxy}{{&c[i*{cols}]}}; }}")
    args = ", ".join(f"{msl_scalar} v{i}" for i in range(n))
    body.append(f"inline {name} {name}_make({args}) {{")
    body.append(f"    {name} r;")
    for i in range(n):
        body.append(f"    r.c[{i}] = v{i};")
    body.append("    return r;")
    body.append("}")
    # Single-scalar broadcast: ``mat23(0.0)`` zero-fills. At 1x1 this has
    # the same signature as the flat per-element factory above — skip it
    # (mirrors the big-vec n == 1 case).
    if n > 1:
        body.append(f"inline {name} {name}_make({msl_scalar} v) {{")
        body.append(f"    {name} r;")
        for i in range(n):
            body.append(f"    r.c[{i}] = v;")
        body.append("    return r;")
        body.append("}")
    # Copy overload: ``mat_t<R, C>(m)`` with a same-type operand.
    body.append(f"inline {name} {name}_make({name} m) {{ return m; }}")
    body.append(f"inline {msl_scalar} wp_mat_extract({name} m, int row, int col) {{ return m.c[row * {cols} + col]; }}")
    body.append(
        f"inline void wp_mat_elem_store(thread {name}& m, int row, int col, {msl_scalar} v) "
        f"{{ m.c[row * {cols} + col] = v; }}"
    )
    # Single-index row read/write for ``wp::extract(m, i)`` and the 3-arg
    # ``*_inplace(m, i, v)`` forms. Concrete overloads so the row comes back
    # by value — the generic ``wp_extract`` template would deduce the row-ref
    # proxy type, which dangles once the by-value matrix copy dies.
    row_get = row_make.replace("c[i", "m.c[i")
    body.append(f"inline {row_type} wp_extract({name} m, int i) {{ return {row_get}; }}")
    vcomp = "v[{j}]" if row_type == f"{msl_scalar}{cols}" else "v.c[{j}]"
    row_stores = "; ".join(f"m.c[i * {cols} + {j}] = {vcomp.format(j=j)}" for j in range(cols))
    body.append(f"inline void wp_index_store(thread {name}& m, int i, {row_type} v) {{ {row_stores}; }}")

    # ---- Arithmetic ----------------------------------------------------
    # Element-wise binary ops, scalar scale, and matrix products. The vec
    # operand/result types mirror the row-type selection above: native
    # ``{msl_scalar}{n}`` for n in 2..4, custom ``wp_vecN_<scalar>`` struct
    # otherwise (whose components live in ``.c[]``).
    def _vec_ty(n: int) -> tuple[str, str]:
        if _vec_native(n, msl_scalar) and msl_scalar in _MSL_PREFIX_TO_SAME:
            return f"{msl_scalar}{n}", "[{k}]"
        return f"wp_vec{n}_{msl_scalar}", ".c[{k}]"

    col_vec_ty, col_at = _vec_ty(cols)  # operand of mat * vec
    row_vec_ty, row_at = _vec_ty(rows)  # result of mat * vec
    if msl_scalar == _F64_EMU_MSL and rows == cols and rows in (1, 2, 3, 4):
        body.append(_emit_f64_square_mat_helpers(name, rows))
    # ``wp_get_diag`` for square big mats (the native sizes come from
    # ``_MISC_MATH_HELPERS``, the float 1x1 one from the ``need_mat1x1`` block).
    if rows == cols and (rows > 1 or msl_scalar == _F64_EMU_MSL):
        diag = ", ".join(f"m.c[{i * cols + i}]" for i in range(rows))
        body.append(
            f"inline {row_vec_ty} wp_get_diag({name} m) {{ return {_msl_vec_ctor(rows, msl_scalar)}({diag}); }}"
        )
    for op in ("+", "-"):
        body.append(f"inline {name} operator{op}({name} a, {name} b) {{")
        body.append(f"    {name} r;")
        body.append(f"    for (int i = 0; i < {n}; ++i) r.c[i] = a.c[i] {op} b.c[i];")
        body.append("    return r;")
        body.append("}")
    body.append(f"inline {name} operator-({name} a) {{")
    body.append(f"    {name} r;")
    body.append(f"    for (int i = 0; i < {n}; ++i) r.c[i] = -a.c[i];")
    body.append("    return r;")
    body.append("}")
    # Compound assignment — needed by the generic reverse-mode templates
    # for the same reason as the big-vec structs (see ``_emit_vec_struct``):
    # ``operator+`` does not imply ``operator+=``.
    for op in ("+", "-"):
        body.append(f"inline thread {name}& operator{op}=(thread {name}& a, {name} b) {{")
        body.append(f"    for (int i = 0; i < {n}; ++i) a.c[i] {op}= b.c[i];")
        body.append("    return a;")
        body.append("}")
    for op in ("*", "/"):
        body.append(f"inline thread {name}& operator{op}=(thread {name}& a, {msl_scalar} s) {{")
        body.append(f"    for (int i = 0; i < {n}; ++i) a.c[i] {op}= s;")
        body.append("    return a;")
        body.append("}")
    for lhs, rhs, expr in (
        (f"{name} a", f"{msl_scalar} s", "a.c[i] * s"),
        (f"{msl_scalar} s", f"{name} a", "s * a.c[i]"),
    ):
        body.append(f"inline {name} operator*({lhs}, {rhs}) {{")
        body.append(f"    {name} r;")
        body.append(f"    for (int i = 0; i < {n}; ++i) r.c[i] = {expr};")
        body.append("    return r;")
        body.append("}")
    body.append(f"inline {name} operator/({name} a, {msl_scalar} s) {{")
    body.append(f"    {name} r;")
    body.append(f"    for (int i = 0; i < {n}; ++i) r.c[i] = a.c[i] / s;")
    body.append("    return r;")
    body.append("}")
    # mat * vec: (rows x cols) * vecC -> vecR
    body.append(f"inline {row_vec_ty} operator*({name} m, {col_vec_ty} v) {{")
    body.append(f"    {row_vec_ty} r;")
    for i in range(rows):
        terms = " + ".join(f"m.c[{i * cols + k}] * v{col_at.format(k=k)}" for k in range(cols))
        body.append(f"    r{row_at.format(k=i)} = {terms};")
    body.append("    return r;")
    body.append("}")
    # vec * mat: vecR * (rows x cols) -> vecC (v^T M)
    body.append(f"inline {col_vec_ty} operator*({row_vec_ty} v, {name} m) {{")
    body.append(f"    {col_vec_ty} r;")
    for j in range(cols):
        terms = " + ".join(f"v{row_at.format(k=k)} * m.c[{k * cols + j}]" for k in range(rows))
        body.append(f"    r{col_at.format(k=j)} = {terms};")
    body.append("    return r;")
    body.append("}")
    # Equality / inequality reduce to scalar bool like the big-vec structs
    # (Warp semantics: ``==`` is all-equal, ``!=`` is any-not-equal).
    body.append(f"inline bool operator==({name} a, {name} b) {{")
    body.append(f"    for (int i = 0; i < {n}; ++i) {{ if (a.c[i] != b.c[i]) return false; }}")
    body.append("    return true;")
    body.append("}")
    body.append(f"inline bool operator!=({name} a, {name} b) {{ return !(a == b); }}")
    # Double-dot (Frobenius inner) product. The native-shape overloads in
    # ``_MISC_MATH_HELPERS`` only cover square ``floatNxN``, so a big-mat
    # operand (warp.fem's ``mat_t<2, 3>`` reference gradients) has no
    # viable candidate without this one.
    body.append(f"inline {msl_scalar} wp_ddot({name} a, {name} b) {{")
    body.append(f"    {msl_scalar} s = {_sc_zero(msl_scalar)};")
    body.append(f"    for (int i = 0; i < {n}; ++i) s += a.c[i] * b.c[i];")
    body.append("    return s;")
    body.append("}")
    if rows == cols:
        # mat * mat (square — same struct type on both sides).
        body.append(f"inline {name} operator*({name} a, {name} b) {{")
        body.append(f"    {name} r;")
        body.append(f"    for (int i = 0; i < {rows}; ++i)")
        body.append(f"    for (int j = 0; j < {cols}; ++j) {{")
        body.append(f"        {msl_scalar} s = {_sc_zero(msl_scalar)};")
        body.append(f"        for (int k = 0; k < {cols}; ++k) s += a.c[i * {cols} + k] * b.c[k * {cols} + j];")
        body.append(f"        r.c[i * {cols} + j] = s;")
        body.append("    }")
        body.append("    return r;")
        body.append("}")
    return "\n".join(body)


_NATIVE_MAT_NAME_PAT = re.compile(r"\b(float|int|uint)([234])x([234])\b")


def _mat_shape_msl_name(shape: tuple[int, int, str]) -> str:
    """``(rows, cols, scalar)`` -> its MSL type name."""
    rows, cols, scalar = shape
    return _msl_mat_name(rows, cols, scalar)


def _is_native_mat_shape(shape: tuple[int, int, str]) -> bool:
    """True when ``shape`` is an MSL-native matrix rather than our struct.

    Derived from ``_msl_mat_name`` rather than restating its rule — the two
    diverging is exactly what produced ``int2x2`` (a type MSL doesn't have)
    for the ``mat2x6 * mat6x2`` integer product.
    """
    return not _mat_shape_msl_name(shape).startswith("wp_mat")


def _mat_product_pairs(
    big_shapes: set[tuple[int, int, str]], source: str
) -> list[tuple[tuple[int, int, str], tuple[int, int, str], tuple[int, int, str]]]:
    """Return ``(lhs, rhs, result)`` shapes for every emittable mat product.

    MSL resolves native-square by native-square itself, so only pairs with
    at least one big-mat operand are listed. The candidate set is the big
    shapes plus whichever native square matrices the kernel names — a
    ``mat_t<3, 2>`` times a ``mat33`` is exactly warp.fem's deformation-
    gradient shape.
    """
    natives: set[tuple[int, int, str]] = set()
    for m in _NATIVE_MAT_NAME_PAT.finditer(source):
        shape = (int(m.group(2)), int(m.group(3)), m.group(1))
        if _is_native_mat_shape(shape):
            natives.add(shape)
    out = []
    candidates = sorted(big_shapes | natives)
    for lhs in candidates:
        for rhs in candidates:
            if lhs[2] != rhs[2] or lhs[1] != rhs[0]:
                continue
            if _is_native_mat_shape(lhs) and _is_native_mat_shape(rhs):
                continue  # MSL's own operator*
            result = (lhs[0], rhs[1], lhs[2])
            if lhs == rhs and result == lhs:
                continue  # square same-type product: emitted with the struct
            out.append((lhs, rhs, result))
    return out


def _emit_big_mat_cross_overloads(
    shapes: list[tuple[int, int, str]],
    pairs: list[tuple[tuple[int, int, str], tuple[int, int, str], tuple[int, int, str]]],
) -> str:
    """Emit big-mat overloads that span two matrix types.

    Covers ``wp_transpose``, ``wp_matrix_from_cols`` / ``wp_matrix_from_rows``,
    and ``operator*`` for the shape pairs in ``pairs``. These can't live in
    ``_emit_big_mat_struct`` because each one names a second matrix type
    that must already be declared.
    """
    body: list[str] = []

    def _vec_name(n: int, scalar: str) -> str:
        return _msl_vec_name(n, scalar)

    for rows, cols, scalar in shapes:
        name = f"wp_mat{rows}x{cols}_{scalar}"
        # transpose: (rows x cols) -> (cols x rows), row-major on both sides.
        t_name = _mat_shape_msl_name((cols, rows, scalar))
        body.append(f"inline {t_name} wp_transpose({name} m) {{")
        if _is_native_mat_shape((cols, rows, scalar)):
            # Native MSL matrices are column-major: element (r, c) of the
            # result is ``t[c][r]``, and the result's (r, c) is m's (c, r).
            body.append(f"    {t_name} t;")
            body.append(f"    for (int r = 0; r < {cols}; ++r)")
            body.append(f"    for (int c = 0; c < {rows}; ++c) t[c][r] = m.c[c * {cols} + r];")
        else:
            body.append(f"    {t_name} t;")
            body.append(f"    for (int r = 0; r < {cols}; ++r)")
            body.append(f"    for (int c = 0; c < {rows}; ++c) t.c[r * {rows} + c] = m.c[c * {cols} + r];")
        body.append("    return t;")
        body.append("}")
        # matrix_from_cols / matrix_from_rows for the non-square shapes
        # (the square native sizes are covered by ``_MISC_MATH_HELPERS``).
        col_vec = _vec_name(rows, scalar)
        col_at = "[{k}]" if rows in _MSL_VEC_NATIVE_N else ".c[{k}]"
        params = ", ".join(f"{col_vec} c{j}" for j in range(cols))
        body.append(f"inline {name} wp_matrix_from_cols({params}) {{")
        body.append(f"    {name} m;")
        for j in range(cols):
            for r in range(rows):
                body.append(f"    m.c[{r * cols + j}] = c{j}{col_at.format(k=r)};")
        body.append("    return m;")
        body.append("}")
        row_vec = _vec_name(cols, scalar)
        row_at = "[{k}]" if cols in _MSL_VEC_NATIVE_N else ".c[{k}]"
        params = ", ".join(f"{row_vec} r{i}" for i in range(rows))
        body.append(f"inline {name} wp_matrix_from_rows({params}) {{")
        body.append(f"    {name} m;")
        for i in range(rows):
            for c in range(cols):
                body.append(f"    m.c[{i * cols + c}] = r{i}{row_at.format(k=c)};")
        body.append("    return m;")
        body.append("}")

    for lhs, rhs, result in pairs:
        l_name, r_name, o_name = (_mat_shape_msl_name(s) for s in (lhs, rhs, result))
        m_rows, inner, n_cols = lhs[0], lhs[1], rhs[1]
        # Element access differs by storage order: our structs are
        # row-major ``c[r * cols + c]``, native MSL matrices are
        # column-major ``m[col][row]``.
        l_native, r_native, o_native = (_is_native_mat_shape(s) for s in (lhs, rhs, result))
        body.append(f"inline {o_name} operator*({l_name} a, {r_name} b) {{")
        body.append(f"    {o_name} r;")
        for i in range(m_rows):
            for j in range(n_cols):
                terms = " + ".join(
                    f"{f'a[{k}][{i}]' if l_native else f'a.c[{i * inner + k}]'} * "
                    f"{f'b[{j}][{k}]' if r_native else f'b.c[{k * n_cols + j}]'}"
                    for k in range(inner)
                )
                dst = f"r[{j}][{i}]" if o_native else f"r.c[{i * n_cols + j}]"
                body.append(f"    {dst} = {terms};")
        body.append("    return r;")
        body.append("}")
    return "\n".join(body)


def _emit_slice_t_struct(source: str) -> str:
    """Emit the ``wp_slice_t`` struct definition if any kernel statement
    references it.  ``wp_slice_t`` is the MSL counterpart of
    ``wp::slice_t`` (start/stop/step ints) and is generated by matrix
    slicing builtins. The struct emit is independent of which matrix
    types appear in the kernel; some kernels declare a slice without
    using it on a native matrix (e.g. mujoco_warp's ``tendon_bias``
    builds slices over big-vec storage).
    """
    if "wp::slice_t" not in source and "wp_slice_t" not in source:
        return ""
    return "struct wp_slice_t { int start; int stop; int step; };"


def _emit_native_mat_extract_overloads(source: str) -> str:
    """Emit ``wp_mat_extract`` overloads for each native ``floatRxC`` /
    ``intRxC`` referenced in the kernel source.

    Native MSL matrices are column-major, so ``m[c][r]`` reads logical row
    ``r``, column ``c``. Wrapping that as a free function lets the same
    ``wp_mat_extract`` translation work for both native and big-mat types
    via overload resolution.

    Also emits slice-overloads of ``wp_mat_extract`` for the row/col
    slice cases (``mat[:, c]`` / ``mat[r, :]``).
    """
    seen: set[tuple[str, int, int]] = set()
    for m in _NATIVE_MAT_NAME_PAT.finditer(source):
        seen.add((m.group(1), int(m.group(2)), int(m.group(3))))
    if not seen:
        return ""
    parts: list[str] = []
    needs_slice = "wp::slice_t" in source or "wp_slice_t" in source
    for scalar, rows, cols in sorted(seen):
        parts.append(
            f"inline {scalar} wp_mat_extract({scalar}{rows}x{cols} m, int row, int col) {{ return m[col][row]; }}"
        )
        # MSL matrices have no unary minus, and ``wp::neg`` lowers to ``(-x)``.
        if scalar in _MSL_NATIVE_MAT_SCALARS:
            parts.append(
                f"inline {scalar}{rows}x{cols} operator-({scalar}{rows}x{cols} m) {{ return m * ({scalar})(-1); }}"
            )
        # Writable element access for ``m[r, c] = v`` (4-arg ``assign_inplace``
        # and friends). Same column-major swap as ``wp_mat_extract``. A
        # reference-returning helper won't compile — MSL forbids binding a
        # non-const reference to a vector element — but direct subscript
        # assignment is legal, so this is a store function.
        parts.append(
            f"inline void wp_mat_elem_store(thread {scalar}{rows}x{cols}& m, int row, int col, {scalar} v) "
            f"{{ m[col][row] = v; }}"
        )
        if needs_slice:
            # Row-slice: extract a vec spanning a row range at a fixed
            # col. The vec length follows the matrix row count (``[:, c]``
            # — full slice). Apple's MSL builds with NDEBUG, so the
            # vec-length parameter ``N`` from ``wp::extract<N>`` need not
            # be threaded through; full-slice vec dim is ``rows``.
            parts.append(
                f"inline {scalar}{rows} wp_mat_extract({scalar}{rows}x{cols} m, wp_slice_t s, int col) {{\n"
                f"    {scalar}{rows} ret = {scalar}{rows}(0);\n"
                f"    int ii = 0;\n"
                f"    for (int i = s.start; (s.step > 0) ? (i < s.stop) : (i > s.stop); i += s.step) {{\n"
                f"        ret[ii++] = m[col][i];\n"
                f"    }}\n"
                f"    return ret;\n"
                f"}}"
            )
            # Col-slice: vec spanning a col range at a fixed row.
            parts.append(
                f"inline {scalar}{cols} wp_mat_extract({scalar}{rows}x{cols} m, int row, wp_slice_t s) {{\n"
                f"    {scalar}{cols} ret = {scalar}{cols}(0);\n"
                f"    int ii = 0;\n"
                f"    for (int i = s.start; (s.step > 0) ? (i < s.stop) : (i > s.stop); i += s.step) {{\n"
                f"        ret[ii++] = m[i][row];\n"
                f"    }}\n"
                f"    return ret;\n"
                f"}}"
            )
    return "\n".join(parts)


# Matched against the translated source (like ``_emit_slice_t_struct``):
# by header-assembly time ``wp::extract`` / ``wp::*_inplace`` have already
# been rewritten to ``wp_extract(`` / ``wp_index_store(`` calls.
_WP_EXTRACT_NEEDED_PAT = re.compile(r"\bwp_(extract|index_store)\s*\(")

# ``wp_extract(<arr>_shape, k)`` after subscript substitution — fold back to
# the ``<arr>_shape[k]`` subscript form the packed-shape rewrite expects.
# The ``(?!var_)`` guard keeps ordinary ``var_*`` locals (which happen to
# end in ``_shape`` only if a user named one that way) out of the fold.
_SHAPE_EXTRACT_FOLD_PAT = re.compile(r"\bwp_extract\s*\(\s*((?!var_)\w+_shape)\s*,\s*([^()]+?)\s*\)")


def _emit_wp_extract_helpers(source: str) -> str:
    """Emit ``wp_extract`` / ``wp_index_store`` single-index helpers.

    ``wp::extract(x, i)`` and the 3-arg ``*_inplace(x, i, v)`` forms mean
    "component i" for vectors but "row i" for matrices, and the regex
    translator has no type information. Overload resolution supplies it
    instead:

    - A by-value template forwards to ``x[i]`` — correct for native MSL
      vectors, quats (normalized to ``float4``), and the big-vec structs.
    - Square native matrices get concrete overloads that read/write the
      logical ROW. Native MSL matrices are column-major (warp ``(r, c)``
      lives at ``m[c][r]``), so ``m[i]`` is a column — the source of a
      silent transpose bug in row reads/writes before these overloads.
    - Big-mat structs emit their own concrete overloads next to their
      struct definition (their row-ref proxy must not escape through the
      template's ``auto`` return, which would dangle).

    Non-square small mats use the custom row-major structs, so only the
    square native sizes need the swap here.
    """
    if not _WP_EXTRACT_NEEDED_PAT.search(source):
        return ""
    parts: list[str] = [
        "template <typename T> inline auto wp_extract(T v, int i) { return v[i]; }",
        "template <typename T, typename V> inline void wp_index_store(thread T& t, int i, V v) { t[i] = v; }",
    ]
    seen: set[tuple[str, int]] = set()
    for m in _NATIVE_MAT_NAME_PAT.finditer(source):
        if m.group(2) == m.group(3):
            seen.add((m.group(1), int(m.group(2))))
    for scalar, n in sorted(seen):
        row = ", ".join(f"m[{c}][i]" for c in range(n))
        parts.append(f"inline {scalar}{n} wp_extract({scalar}{n}x{n} m, int i) {{ return {scalar}{n}({row}); }}")
        stores = " ".join(f"m[{c}][i] = v[{c}];" for c in range(n))
        parts.append(f"inline void wp_index_store(thread {scalar}{n}x{n}& m, int i, {scalar}{n} v) {{ {stores} }}")
    return "\n".join(parts)


_NATIVE_VEC_NAME_PAT = re.compile(r"\b(float|int|uint)([234])\b")


def _emit_wp_dot_overloads(source: str) -> str:
    """Emit ``wp_dot`` overloads for every vector type used in ``source``.

    MSL's ``metal::dot`` only knows about its native ``floatN`` etc.; our
    custom ``wp_vecN_<scalar>`` big-vec structs need a hand-rolled
    sum-of-products. Wrapping the call as ``wp_dot`` lets the codegen emit
    one uniform translation regardless of operand type — the C++ overload
    resolver picks the right body.
    """
    parts: list[str] = []
    seen_native: set[tuple[str, int]] = set()
    for m in _NATIVE_VEC_NAME_PAT.finditer(source):
        seen_native.add((m.group(1), int(m.group(2))))
    for scalar, n in sorted(seen_native):
        # ``metal::dot`` is float/half-only; integer overloads have to be
        # hand-rolled as a sum-of-products.
        if scalar in ("int", "uint"):
            body_terms = " + ".join(f"a[{i}] * b[{i}]" for i in range(n))
            parts.append(f"inline {scalar} wp_dot({scalar}{n} a, {scalar}{n} b) {{ return {body_terms}; }}")
        else:
            parts.append(f"inline {scalar} wp_dot({scalar}{n} a, {scalar}{n} b) {{ return metal::dot(a, b); }}")

    seen_big: set[tuple[int, str]] = set()
    for m in _BIG_VEC_NAME_PAT.finditer(source):
        n = int(m.group(1))
        scalar = m.group(2)
        if scalar not in _MSL_PREFIX_TO_SAME or _vec_native(n, scalar):
            continue
        seen_big.add((n, scalar))
    for n, scalar in sorted(seen_big):
        body_terms = " + ".join(f"a.c[{i}] * b.c[{i}]" for i in range(n))
        parts.append(f"inline {scalar} wp_dot(wp_vec{n}_{scalar} a, wp_vec{n}_{scalar} b) {{ return {body_terms}; }}")
    return "\n".join(parts)


# Overload set so ``wp::diag(v)`` resolves by the argument's vector
# width — the IR line carries no type info (warp.fem's Grid2D path
# passes float2, mujoco_warp passes float3).
_DIAG_HELPERS = (
    "inline float2x2 wp_diag_float3(float2 v) {\n"
    "    return float2x2(float2(v[0], 0.0f), float2(0.0f, v[1]));\n"
    "}\n"
    "inline float3x3 wp_diag_float3(float3 v) {\n"
    "    return float3x3(float3(v[0], 0.0f, 0.0f), "
    "float3(0.0f, v[1], 0.0f), "
    "float3(0.0f, 0.0f, v[2]));\n"
    "}\n"
    "inline float4x4 wp_diag_float3(float4 v) {\n"
    "    return float4x4(float4(v[0], 0.0f, 0.0f, 0.0f), "
    "float4(0.0f, v[1], 0.0f, 0.0f), "
    "float4(0.0f, 0.0f, v[2], 0.0f), "
    "float4(0.0f, 0.0f, 0.0f, v[3]));\n"
    "}"
)


# Software demotion of IEEE-754 double bits to fp32 — Apple GPUs have no
# fp64, so float64 struct fields (warp.fem's ``wp.float64`` integrand
# parameters ride in the ValueStruct) are read as their raw 64 bits and
# converted here. Truncating (round-toward-zero) mantissa conversion;
# handles inf/NaN, overflow to inf, and flushes underflow/denormals to 0.
def _fp64_mode() -> str:
    """Resolve :data:`warp.config.metal_fp64` (``"error"`` / ``"demote"`` /
    ``"emulate"``), honouring the deprecated ``metal_demote_fp64`` alias."""
    import warp.config as _wp_cfg  # noqa: PLC0415

    mode = getattr(_wp_cfg, "metal_fp64", "error")
    if mode == "error" and getattr(_wp_cfg, "metal_demote_fp64", False):
        return "demote"
    if mode not in ("error", "demote", "emulate"):
        raise MetalCodegenError(f"warp.config.metal_fp64 must be one of 'error', 'demote', 'emulate' (got {mode!r})")
    return mode


def _f64_lit(value) -> str:
    """MSL aggregate literal of an emulated double from a Python number."""
    import struct as _struct  # noqa: PLC0415

    bits = _struct.unpack("<Q", _struct.pack("<d", float(value)))[0]
    return f"wp_f64{{0x{bits:016x}UL}}"


def _sc_zero(msl_scalar: str) -> str:
    """A zero of ``msl_scalar`` (the POD ``wp_f64`` has no converting ctor)."""
    return "wp_f64{}" if msl_scalar == _F64_EMU_MSL else f"({msl_scalar})0"


def _sc_lit(msl_scalar: str, value) -> str:
    """A numeric literal of ``msl_scalar``."""
    if msl_scalar == _F64_EMU_MSL:
        return _f64_lit(value)
    if msl_scalar in ("float", "half"):
        return f"({msl_scalar}){float(value)!r}f"
    return f"({msl_scalar}){value}"


def _sc_cast(msl_scalar: str, expr: str) -> str:
    """Convert ``expr`` (a native scalar expression) to ``msl_scalar``."""
    if msl_scalar == _F64_EMU_MSL:
        return f"wp_f64_from({expr})"
    return f"({msl_scalar})({expr})"


_F64_EMU_HELPERS_CACHE: str | None = None

# Conversions between the emulated double and every native scalar. Each
# entry is (MSL type, expression producing ``wp_f64`` from ``x``,
# expression producing the native type from ``wp_f64 v``).
_F64_EMU_SCALAR_CONVERSIONS: tuple[tuple[str, str, str], ...] = (
    (
        "float",
        "wp_f64_bits(__softfloat64_cvt_f32_to_f64(as_type<uint>(x)))",
        "as_type<float>(__softfloat64_cvt_f64_to_f32(v.bits, WP_F64_RM))",
    ),
    ("half", "wp_f64_from(float(x))", "half(float(v))"),
    ("long", "wp_f64_bits(__softfloat64_cvt_i64_to_f64(x, WP_F64_RM))", "__softfloat64_cvt_f64_to_i64(v.bits, 3u)"),
    ("ulong", "wp_f64_bits(__softfloat64_cvt_u64_to_f64(x, WP_F64_RM))", "ulong(long(v))"),
    ("int", "wp_f64_from(long(x))", "int(long(v))"),
    ("uint", "wp_f64_from(long(x))", "uint(long(v))"),
    ("short", "wp_f64_from(long(x))", "short(long(v))"),
    ("ushort", "wp_f64_from(long(x))", "ushort(long(v))"),
    ("char", "wp_f64_from(long(x))", "char(long(v))"),
    ("uchar", "wp_f64_from(long(x))", "uchar(long(v))"),
    ("bool", "wp_f64_from(long(x ? 1 : 0))", "(v.bits & 0x7fffffffffffffffUL) != 0UL"),
)

# Transcendentals evaluated in fp32 and widened (see ``warp.config.metal_fp64``).
_F64_EMU_FP32_UNARY = (
    "exp",
    "exp2",
    "log",
    "log2",
    "log10",
    "sin",
    "cos",
    "tan",
    "asin",
    "acos",
    "atan",
    "sinh",
    "cosh",
    "tanh",
)
_F64_EMU_FP32_BINARY = ("atan2", "pow")


def _f64_emulate_helpers() -> str:
    """The bundled metal-softfloat routines plus the ``wp_f64`` type (cached).

    ``wp_f64`` is deliberately a POD struct with no constructors: MSL
    refuses to place a type with a user-declared constructor in
    ``threadgroup`` memory (smem tiles), so construction goes through
    ``wp_f64{bits}`` aggregate literals and the ``wp_f64_from(x)`` overload
    set, while ``float(x)`` / ``int(x)`` casts *out* of it use explicit
    conversion operators (allowed on PODs). Arithmetic and comparison
    operators, compound assignment in every address space, and overloads of
    the ``metal::`` math functions the translators emit make the existing
    scalar-templated helpers (big-vec / big-mat structs, tile helpers)
    instantiate unchanged.
    """
    global _F64_EMU_HELPERS_CACHE
    if _F64_EMU_HELPERS_CACHE is not None:
        return _F64_EMU_HELPERS_CACHE
    path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "native", "metal", "softfloat64.metal")
    with open(path, encoding="utf-8") as f:
        soft = f.read()
    L: list[str] = []
    L.append("// ---- metal-softfloat (warp/native/metal/softfloat64.metal) ----")
    L.append(soft)
    L.append("// ---- wp_f64: emulated IEEE-754 binary64 (warp.config.metal_fp64 = 'emulate') ----")
    L.append("#define WP_F64_RM 0u  // round-to-nearest-even, as CPU / CUDA")
    L.append("struct wp_f64 {")
    L.append("    ulong bits;")
    for msl, _to, frm in _F64_EMU_SCALAR_CONVERSIONS:
        for space in ("thread", "device", "constant", "threadgroup"):
            L.append(f"    explicit operator {msl}() const {space} {{ wp_f64 v = *this; return {frm}; }}")
    L.append("};")
    L.append("inline wp_f64 wp_f64_bits(ulong b) { wp_f64 r; r.bits = b; return r; }")
    L.append("inline wp_f64 wp_f64_from(wp_f64 x) { return x; }")
    for msl, to, _frm in _F64_EMU_SCALAR_CONVERSIONS:
        L.append(f"inline wp_f64 wp_f64_from({msl} x) {{ return {to}; }}")
    for op, fn in (("+", "fadd"), ("-", "fsub"), ("*", "fmul"), ("/", "fdiv")):
        L.append(
            f"inline wp_f64 operator{op}(wp_f64 a, wp_f64 b) "
            f"{{ return wp_f64_bits(__softfloat64_{fn}(a.bits, b.bits, WP_F64_RM)); }}"
        )
        for space in ("thread", "device", "threadgroup"):
            L.append(f"inline {space} wp_f64& operator{op}=({space} wp_f64& a, wp_f64 b) {{ a = a {op} b; return a; }}")
    L.append("inline wp_f64 operator-(wp_f64 a) { return wp_f64_bits(a.bits ^ 0x8000000000000000UL); }")
    L.append("inline wp_f64 operator+(wp_f64 a) { return a; }")
    for op, fn in (("<", "flt"), ("<=", "fle"), (">", "fgt"), (">=", "fge"), ("==", "feq")):
        L.append(f"inline bool operator{op}(wp_f64 a, wp_f64 b) {{ return __softfloat64_{fn}(a.bits, b.bits); }}")
    L.append("inline bool operator!=(wp_f64 a, wp_f64 b) { return !__softfloat64_feq(a.bits, b.bits); }")
    # Exact bit-level helpers.
    L.append("inline wp_f64 wp_f64_trunc(wp_f64 x) {")
    L.append("    int e = int((x.bits >> 52) & 0x7ffUL) - 1023;")
    L.append("    if (e >= 52) return x;  // already integral (or inf / nan)")
    L.append("    if (e < 0) return wp_f64_bits(x.bits & 0x8000000000000000UL);  // |x| < 1 -> +-0")
    L.append("    return wp_f64_bits(x.bits & ~((1UL << (52 - e)) - 1UL));")
    L.append("}")
    L.append("inline wp_f64 wp_f64_floor(wp_f64 x) {")
    L.append("    wp_f64 t = wp_f64_trunc(x);")
    L.append("    return (x < t) ? t - wp_f64{0x3ff0000000000000UL} : t;")
    L.append("}")
    L.append("inline wp_f64 wp_f64_ceil(wp_f64 x) {")
    L.append("    wp_f64 t = wp_f64_trunc(x);")
    L.append("    return (t < x) ? t + wp_f64{0x3ff0000000000000UL} : t;")
    L.append("}")
    L.append("inline wp_f64 wp_f64_copysign(wp_f64 a, wp_f64 b) {")
    L.append("    return wp_f64_bits((a.bits & 0x7fffffffffffffffUL) | (b.bits & 0x8000000000000000UL));")
    L.append("}")
    L.append("inline wp_f64 wp_f64_abs(wp_f64 a) { return wp_f64_bits(a.bits & 0x7fffffffffffffffUL); }")
    # round half away from zero (C ``round``); rint = ties-to-even.
    L.append("inline wp_f64 wp_f64_round(wp_f64 x) {")
    L.append("    wp_f64 t = wp_f64_trunc(x);")
    L.append("    wp_f64 d = wp_f64_abs(x - t);  // exact: |x| < 2^52 here or t == x")
    L.append("    if (!(d < wp_f64{0x3fe0000000000000UL})) t = t + wp_f64_copysign(wp_f64{0x3ff0000000000000UL}, x);")
    L.append("    return t;")
    L.append("}")
    L.append("inline wp_f64 wp_f64_rint(wp_f64 x) {")
    L.append("    wp_f64 t = wp_f64_trunc(x);")
    L.append("    wp_f64 d = wp_f64_abs(x - t);")
    L.append("    wp_f64 half_ = wp_f64{0x3fe0000000000000UL}, one = wp_f64{0x3ff0000000000000UL};")
    L.append("    if (half_ < d) return t + wp_f64_copysign(one, x);")
    L.append("    if (d == half_) {  // tie: pick the even neighbour")
    L.append("        wp_f64 h = t * half_;")
    L.append("        if (!(wp_f64_trunc(h) == h)) return t + wp_f64_copysign(one, x);")
    L.append("    }")
    L.append("    return t;")
    L.append("}")
    L.append("inline bool wp_f64_isnan(wp_f64 a) { return (a.bits & 0x7fffffffffffffffUL) > 0x7ff0000000000000UL; }")
    L.append("inline bool wp_f64_isinf(wp_f64 a) { return (a.bits & 0x7fffffffffffffffUL) == 0x7ff0000000000000UL; }")
    L.append(
        "inline bool wp_f64_isfinite(wp_f64 a) { return (a.bits & 0x7ff0000000000000UL) != 0x7ff0000000000000UL; }"
    )
    L.append("namespace metal {")
    L.append("inline wp_f64 sqrt(wp_f64 a) { return wp_f64_bits(__softfloat64_fsqrt(a.bits, WP_F64_RM)); }")
    L.append("inline wp_f64 rsqrt(wp_f64 a) { return wp_f64{0x3ff0000000000000UL} / metal::sqrt(a); }")
    L.append(
        "inline wp_f64 fma(wp_f64 a, wp_f64 b, wp_f64 c) "
        "{ return wp_f64_bits(__softfloat64_fma(a.bits, b.bits, c.bits, WP_F64_RM)); }"
    )
    L.append("inline wp_f64 abs(wp_f64 a) { return wp_f64_abs(a); }")
    L.append("inline wp_f64 fabs(wp_f64 a) { return wp_f64_abs(a); }")
    L.append("inline wp_f64 min(wp_f64 a, wp_f64 b) { return (b < a) ? b : a; }")
    L.append("inline wp_f64 max(wp_f64 a, wp_f64 b) { return (a < b) ? b : a; }")
    L.append("inline wp_f64 clamp(wp_f64 x, wp_f64 lo, wp_f64 hi) { return metal::min(metal::max(x, lo), hi); }")
    L.append("inline wp_f64 floor(wp_f64 a) { return wp_f64_floor(a); }")
    L.append("inline wp_f64 ceil(wp_f64 a) { return wp_f64_ceil(a); }")
    L.append("inline wp_f64 trunc(wp_f64 a) { return wp_f64_trunc(a); }")
    L.append("inline wp_f64 round(wp_f64 a) { return wp_f64_round(a); }")
    L.append("inline wp_f64 rint(wp_f64 a) { return wp_f64_rint(a); }")
    L.append("inline wp_f64 copysign(wp_f64 a, wp_f64 b) { return wp_f64_copysign(a, b); }")
    L.append("inline wp_f64 fmod(wp_f64 a, wp_f64 b) { return a - wp_f64_trunc(a / b) * b; }")
    L.append("inline bool isnan(wp_f64 a) { return wp_f64_isnan(a); }")
    L.append("inline bool isinf(wp_f64 a) { return wp_f64_isinf(a); }")
    L.append("inline bool isfinite(wp_f64 a) { return wp_f64_isfinite(a); }")
    for fn in _F64_EMU_FP32_UNARY:
        L.append(f"inline wp_f64 {fn}(wp_f64 a) {{ return wp_f64_from(metal::precise::{fn}(float(a))); }}")
    for fn in _F64_EMU_FP32_BINARY:
        L.append(
            f"inline wp_f64 {fn}(wp_f64 a, wp_f64 b) "
            f"{{ return wp_f64_from(metal::precise::{fn}(float(a), float(b))); }}"
        )
    # SIMD-group collectives: shuffle the two 32-bit halves. ``simd_sum``
    # runs an xor butterfly (always in range) and then broadcasts lane 0's
    # total so every lane holds the *same* correctly-rounded value — the
    # cooperative Cholesky/solve helpers rely on lane-identical copies.
    L.append("inline wp_f64 simd_shuffle(wp_f64 v, ushort lane) {")
    L.append("    uint lo = metal::simd_shuffle(uint(v.bits & 0xffffffffUL), lane);")
    L.append("    uint hi = metal::simd_shuffle(uint(v.bits >> 32), lane);")
    L.append("    return wp_f64_bits((ulong(hi) << 32) | ulong(lo));")
    L.append("}")
    L.append("inline wp_f64 simd_shuffle_xor(wp_f64 v, ushort mask) {")
    L.append("    uint lo = metal::simd_shuffle_xor(uint(v.bits & 0xffffffffUL), mask);")
    L.append("    uint hi = metal::simd_shuffle_xor(uint(v.bits >> 32), mask);")
    L.append("    return wp_f64_bits((ulong(hi) << 32) | ulong(lo));")
    L.append("}")
    L.append("inline wp_f64 simd_broadcast(wp_f64 v, ushort lane) { return metal::simd_shuffle(v, lane); }")
    for fn, expr in (("simd_sum", "v + o"), ("simd_min", "metal::min(v, o)"), ("simd_max", "metal::max(v, o)")):
        L.append(f"inline wp_f64 {fn}(wp_f64 v) {{")
        L.append(
            "    for (ushort m = 16; m > 0; m >>= 1) { wp_f64 o = metal::simd_shuffle_xor(v, m); v = " + expr + "; }"
        )
        L.append("    return metal::simd_shuffle(v, 0);")
        L.append("}")
    L.append("namespace precise {")
    L.append("inline wp_f64 sqrt(wp_f64 a) { return metal::sqrt(a); }")
    L.append("inline wp_f64 rsqrt(wp_f64 a) { return metal::rsqrt(a); }")
    for fn in _F64_EMU_FP32_UNARY:
        L.append(f"inline wp_f64 {fn}(wp_f64 a) {{ return metal::{fn}(a); }}")
    for fn in _F64_EMU_FP32_BINARY:
        L.append(f"inline wp_f64 {fn}(wp_f64 a, wp_f64 b) {{ return metal::{fn}(a, b); }}")
    L.append("}  // namespace precise")
    L.append("}  // namespace metal")
    # Non-template overloads of the ``wp_*`` scalar helpers whose generic
    # bodies spell literals as ``T(0)`` (impossible for a POD).
    L.append(
        "inline wp_f64 wp_sign(wp_f64 x) { return (x < wp_f64{}) ? wp_f64{0xbff0000000000000UL} : wp_f64{0x3ff0000000000000UL}; }"
    )
    L.append("inline wp_f64 wp_step(wp_f64 x) { return (x < wp_f64{}) ? wp_f64{0x3ff0000000000000UL} : wp_f64{}; }")
    L.append("inline wp_f64 wp_nonzero(wp_f64 x) { return (x == wp_f64{}) ? wp_f64{} : wp_f64{0x3ff0000000000000UL}; }")
    L.append("inline wp_f64 wp_mod(wp_f64 a, wp_f64 b) { return metal::fmod(a, b); }")
    L.append("inline wp_f64 wp_frac(wp_f64 x) { return x - wp_f64_trunc(x); }")
    L.append("inline wp_f64 wp_degrees(wp_f64 x) { return x * wp_f64{0x404ca5dc1a63c1f8UL}; }")
    L.append("inline wp_f64 wp_radians(wp_f64 x) { return x * wp_f64{0x3f91df46a2529d39UL}; }")
    L.append("inline bool wp_isfinite(wp_f64 x) { return wp_f64_isfinite(x); }")
    # Reverse-mode cast adjoints: the generic ``wp_adj_cast`` template spells
    # the widening as ``T(r)``, which a POD cannot provide.
    L.append(
        "template <typename U> inline void wp_adj_cast(wp_f64 x, thread wp_f64& ax, U r) { ax += wp_f64_from(r); }"
    )
    L.append("inline bool wp_isnan(wp_f64 x) { return wp_f64_isnan(x); }")
    L.append("inline bool wp_isinf(wp_f64 x) { return wp_f64_isinf(x); }")
    _F64_EMU_HELPERS_CACHE = "\n".join(L) + "\n"
    return _F64_EMU_HELPERS_CACHE


# Atomic read-modify-write on an emulated-double element (``"emulate"``
# mode). Same per-element lock protocol as ``_F64_ATOMIC_HELPERS`` below —
# the high word is compare-exchanged to the ``0x7ff7dead`` sentinel — but
# the update itself is a correctly-rounded softfloat op, so the result is
# bit-identical to a serial CPU accumulation in the same order.
_F64_EMU_ATOMIC_HELPERS = """\
#define WP_F64_ATOMIC_LOCK 0x7ff7deadu
#define WP_F64E_ATOMIC_OP(NAME, EXPR) \\
inline wp_f64 wp_f64_atomic_##NAME(device wp_f64* p, wp_f64 v) { \\
    device metal::atomic_uint* hi = ((device metal::atomic_uint*)p) + 1; \\
    device metal::atomic_uint* lo = (device metal::atomic_uint*)p; \\
    while (true) { \\
        uint old_hi = metal::atomic_load_explicit(hi, metal::memory_order_relaxed); \\
        if (old_hi == WP_F64_ATOMIC_LOCK) continue; \\
        if (metal::atomic_compare_exchange_weak_explicit(hi, &old_hi, WP_F64_ATOMIC_LOCK, \\
                                                         metal::memory_order_relaxed, metal::memory_order_relaxed)) { \\
            metal::atomic_thread_fence(metal::mem_flags::mem_device, metal::memory_order_seq_cst, \\
                                       metal::thread_scope::thread_scope_device); \\
            uint old_lo = metal::atomic_load_explicit(lo, metal::memory_order_relaxed); \\
            wp_f64 cur = wp_f64_bits((ulong(old_hi) << 32) | ulong(old_lo)); \\
            wp_f64 nb = (EXPR); \\
            metal::atomic_store_explicit(lo, uint(nb.bits & 0xffffffffUL), metal::memory_order_relaxed); \\
            metal::atomic_thread_fence(metal::mem_flags::mem_device, metal::memory_order_seq_cst, \\
                                       metal::thread_scope::thread_scope_device); \\
            metal::atomic_store_explicit(hi, uint(nb.bits >> 32), metal::memory_order_relaxed); \\
            return cur; \\
        } \\
    } \\
}
WP_F64E_ATOMIC_OP(add, cur + v)
WP_F64E_ATOMIC_OP(sub, cur - v)
WP_F64E_ATOMIC_OP(min, metal::min(cur, v))
WP_F64E_ATOMIC_OP(max, metal::max(cur, v))
// Reverse-mode gradient accumulation into a float64 array (see the float
// ``wp_adj_accum`` in ``_ADJ_HELPERS``): several lanes may hold the adjoint
// of one element, so it goes through the lock-emulated atomic add.
inline void wp_adj_accum(device wp_f64* p, wp_f64 v) { wp_f64_atomic_add(p, v); }
"""


_F64_HELPERS = """\\
inline float wp_f64_to_f32(ulong b) {
    uint sign = uint(b >> 63) << 31;
    int exp = int((b >> 52) & 0x7ffull);
    ulong man = b & 0xfffffffffffffull;
    if (exp == 0x7ff) {  // inf / NaN
        uint m = man ? 0x400000u : 0u;
        return as_type<float>(sign | 0x7f800000u | m);
    }
    if (exp == 0) return as_type<float>(sign);  // double denormal < 1e-308: flush to 0
    int e32 = exp - 1023 + 127;
    if (e32 >= 255) return as_type<float>(sign | 0x7f800000u);  // overflow -> inf
    if (e32 <= 0) return as_type<float>(sign);                  // underflow -> 0
    return as_type<float>(sign | (uint(e32) << 23) | uint(man >> 29));
}
inline ulong wp_f32_to_f64(float f) {
    uint b = as_type<uint>(f);
    ulong sign = ulong(b >> 31) << 63;
    uint exp = (b >> 23) & 0xffu;
    uint man = b & 0x7fffffu;
    if (exp == 0xffu) {  // inf / NaN -- keep the quiet bit
        return sign | (0x7ffull << 52) | (man ? (1ull << 51) : 0ull);
    }
    if (exp == 0) {
        if (man == 0) return sign;  // +/- 0
        // float denormal: renormalise into the double's much wider exponent
        // range, which represents every one of them exactly.
        int e = -126;
        while ((man & 0x800000u) == 0) { man <<= 1; --e; }
        man &= 0x7fffffu;
        return sign | (ulong(e - 1 + 1023) << 52) | (ulong(man) << 29);
    }
    return sign | (ulong(int(exp) - 127 + 1023) << 52) | (ulong(man) << 29);
}
"""


# Atomic read-modify-write on an fp32-demoted float64 element. Metal has no
# 64-bit atomics at all (``atomic<ulong>`` has no load / CAS overload on any
# MSL version — probed), so the 8-byte element is updated under a per-element
# lock carried *inside the element itself*: the high word is compare-exchanged
# from its current value to ``0x7ff7dead`` — a signalling-NaN bit pattern that
# ``wp_f32_to_f64`` never produces (it canonicalises NaN to the quiet
# ``0x7ff8...``) — the holder rewrites both words from a full-precision fp32
# sum, and the final store of the real high word releases the lock. Fences
# order the low-word traffic against the lock word (MSL atomics are relaxed
# only). The critical section sits *inside* the retry loop, so lanes of one
# SIMD group serialise iteration by iteration instead of deadlocking the way
# a lock taken by a spin loop *before* its critical section does on Apple
# GPUs (no independent forward progress — see ``example_spin_lock``).
# Consequences worth knowing: the update is exact fp32 (no further precision
# loss beyond the demotion itself); a plain, racing read of an element that
# is mid-update sees the sentinel NaN for a few instructions (such a read is
# a data race in the source program too); and ``wp.atomic_*`` on a demoted
# element costs one CAS loop plus two fences, so it is far slower than a
# native ``atomic_float`` fetch-add.
_F64_ATOMIC_HELPERS = """\
#define WP_F64_ATOMIC_LOCK 0x7ff7deadu
#define WP_F64_ATOMIC_OP(NAME, EXPR) \\
inline float wp_f64_atomic_##NAME(device ulong* p, float v) { \\
    device metal::atomic_uint* hi = ((device metal::atomic_uint*)p) + 1; \\
    device metal::atomic_uint* lo = (device metal::atomic_uint*)p; \\
    while (true) { \\
        uint old_hi = metal::atomic_load_explicit(hi, metal::memory_order_relaxed); \\
        if (old_hi == WP_F64_ATOMIC_LOCK) continue; \\
        if (metal::atomic_compare_exchange_weak_explicit(hi, &old_hi, WP_F64_ATOMIC_LOCK, \\
                                                         metal::memory_order_relaxed, metal::memory_order_relaxed)) { \\
            metal::atomic_thread_fence(metal::mem_flags::mem_device, metal::memory_order_seq_cst, \\
                                       metal::thread_scope::thread_scope_device); \\
            uint old_lo = metal::atomic_load_explicit(lo, metal::memory_order_relaxed); \\
            float cur = wp_f64_to_f32((ulong(old_hi) << 32) | ulong(old_lo)); \\
            ulong nb = wp_f32_to_f64((EXPR)); \\
            metal::atomic_store_explicit(lo, uint(nb), metal::memory_order_relaxed); \\
            metal::atomic_thread_fence(metal::mem_flags::mem_device, metal::memory_order_seq_cst, \\
                                       metal::thread_scope::thread_scope_device); \\
            metal::atomic_store_explicit(hi, uint(nb >> 32), metal::memory_order_relaxed); \\
            return cur; \\
        } \\
    } \\
}
WP_F64_ATOMIC_OP(add, cur + v)
WP_F64_ATOMIC_OP(sub, cur - v)
WP_F64_ATOMIC_OP(min, metal::min(cur, v))
WP_F64_ATOMIC_OP(max, metal::max(cur, v))
#undef WP_F64_ATOMIC_OP
"""


# ---------------------------------------------------------------------------
# Reverse-mode (adjoint) helpers
#
# Warp's reverse IR calls ``wp::adj_<builtin>(fwd args..., [fwd ret,]
# adj args..., adj ret)`` with the adjoint arguments taken by mutable
# reference. The arities below mirror ``warp/native/*.h`` exactly — an
# arity mismatch would silently bind the wrong operand, so each helper
# is written against the signature grepped from the native header rather
# than inferred.
#
# Adjoint locals live in ``thread`` address space (they are plain kernel
# locals), so ``thread T&`` out-params are the MSL spelling of the
# native ``T&``. Explicit non-template overloads for mixed-type cases
# (vec * scalar) beat the generic template in overload resolution, which
# is why no ``enable_if`` gymnastics are needed.
# ---------------------------------------------------------------------------
_ADJ_HELPERS = """\
template <typename T> inline void wp_adj_add(T a, T b, thread T& aa, thread T& ab, T r) { aa += r; ab += r; }
template <typename T> inline void wp_adj_sub(T a, T b, thread T& aa, thread T& ab, T r) { aa += r; ab -= r; }
template <typename T> inline void wp_adj_mul(T a, T b, thread T& aa, thread T& ab, T r) { aa += b * r; ab += a * r; }
template <typename T> inline void wp_adj_div(T a, T b, T ret, thread T& aa, thread T& ab, T r) {
    aa += r / b;
    ab -= r * ret / b;
}
template <typename T> inline void wp_adj_neg(T x, thread T& ax, T r) { ax -= r; }
// ``T()`` rather than ``T(0)``: these templates are instantiated on the
// generated ``wp_vecN`` / ``wp_matRxC`` PODs too (warp.fem's ``vec1``
// scalar-space dofs), and those have no one-arg constructor. Value-init
// zeroes scalars, MSL's native vectors, and the PODs alike.
template <typename T> inline void wp_adj_copy(T src, thread T& adj_src, thread T& adj_dest) {
    adj_src += adj_dest;
    adj_dest = T();
}
// Matches ``warp/native/builtin.h``: assign is non-differentiable except
// through read-modify-write, where the adjoint MOVES (``=``, not ``+=``).
template <typename T> inline void wp_adj_assign(T dest, T src, thread T& adj_dest, thread T& adj_src) {
    adj_src = adj_dest;
    adj_dest = T();
}
template <typename C, typename T>
inline void wp_adj_where(C c, T a, T b, thread C& ac, thread T& aa, thread T& ab, T r) {
    if (!!c) aa += r; else ab += r;
}
// In-place element writes: ``v[i] op= value`` on a vector (3-arg forward) or
// ``m[i, j] op= value`` on a matrix (4-arg forward). Per ``warp/native/vec.h``
// and ``mat.h`` the whole adjoint is to read the container's dual at that
// index into the value's dual; the container dual is left alone, and the index
// is non-differentiable. ``assign_inplace`` accumulates exactly like
// ``add_inplace`` upstream (it does NOT clear the slot), so it is spelled the
// same way here rather than "corrected" -- matching the reference backend is
// the contract. ``mul_inplace``/``div_inplace`` have no upstream adjoint for
// these arities, so they are deliberately absent and still raise.
// Routed through ``wp_extract``/``wp_mat_extract`` so the ``wp_vecN_*`` and
// ``wp_matRxC_*`` structs and the layout-swapped native matrices are all
// handled by the same overload set the forward pass uses.
template <typename V, typename I, typename T>
inline void wp_adj_add_inplace(V v, I i, T value, thread V& av, I ai, thread T& avalue) {
    avalue += wp_extract(av, (int)i);
}
template <typename V, typename I, typename T>
inline void wp_adj_assign_inplace(V v, I i, T value, thread V& av, I ai, thread T& avalue) {
    avalue += wp_extract(av, (int)i);
}
template <typename V, typename I, typename T>
inline void wp_adj_sub_inplace(V v, I i, T value, thread V& av, I ai, thread T& avalue) {
    avalue -= wp_extract(av, (int)i);
}
template <typename M, typename I, typename T>
inline void wp_adj_add_inplace(M m, I i, I j, T value, thread M& am, I ai, I aj, thread T& avalue) {
    avalue += wp_mat_extract(am, (int)i, (int)j);
}
template <typename M, typename I, typename T>
inline void wp_adj_assign_inplace(M m, I i, I j, T value, thread M& am, I ai, I aj, thread T& avalue) {
    avalue += wp_mat_extract(am, (int)i, (int)j);
}
template <typename M, typename I, typename T>
inline void wp_adj_sub_inplace(M m, I i, I j, T value, thread M& am, I ai, I aj, thread T& avalue) {
    avalue -= wp_mat_extract(am, (int)i, (int)j);
}
template <typename T> inline void wp_adj_sqrt(T x, T ret, thread T& ax, T r) {
    ax += T(0.5) * (T(1) / ret) * r;
}
template <typename T> inline void wp_adj_sin(T x, thread T& ax, T r) { ax += metal::cos(x) * r; }
template <typename T> inline void wp_adj_cos(T x, thread T& ax, T r) { ax -= metal::sin(x) * r; }
template <typename T> inline void wp_adj_exp(T x, T ret, thread T& ax, T r) { ax += ret * r; }
template <typename T> inline void wp_adj_log(T x, thread T& ax, T r) { ax += r / x; }
template <typename T> inline void wp_adj_tanh(T x, T ret, thread T& ax, T r) { ax += r * (T(1) - ret * ret); }
template <typename T> inline void wp_adj_abs(T x, thread T& ax, T r) { ax += x < T(0) ? -r : r; }
template <typename T> inline void wp_adj_min(T a, T b, thread T& aa, thread T& ab, T r) {
    if (a < b) aa += r; else ab += r;
}
template <typename T> inline void wp_adj_max(T a, T b, thread T& aa, thread T& ab, T r) {
    if (a > b) aa += r; else ab += r;
}
template <typename T> inline void wp_adj_clamp(T x, T a, T b, thread T& ax, thread T& aa, thread T& ab, T r) {
    if (x < a) aa += r; else if (x > b) ab += r; else ax += r;
}
// ``mod`` on real types feeds the whole adjoint back through the dividend.
// The integer overload in ``warp/native/builtin.h`` is a no-op, but integer
// adjoints are dead values (no array of integers carries a gradient), so one
// template covers both without a wrong result reaching a float.
template <typename T> inline void wp_adj_mod(T a, T b, thread T& aa, thread T& ab, T r) { aa += r; }
template <typename T> inline void wp_adj_floordiv(T a, T b, thread T& aa, thread T& ab, T r) { }
template <typename T> inline void wp_adj_sign(T x, thread T& ax, T r) { }
template <typename T> inline void wp_adj_step(T x, thread T& ax, T r) { }
template <typename T> inline void wp_adj_nonzero(T x, thread T& ax, T r) { }
template <typename T> inline void wp_adj_round(T x, thread T& ax, T r) { }
template <typename T> inline void wp_adj_rint(T x, thread T& ax, T r) { }
template <typename T> inline void wp_adj_trunc(T x, thread T& ax, T r) { }
template <typename T> inline void wp_adj_floor(T x, thread T& ax, T r) { }
template <typename T> inline void wp_adj_ceil(T x, thread T& ax, T r) { }
template <typename T> inline void wp_adj_isfinite(T x, thread T& ax, bool r) { }
// Guarded exactly as ``warp/native/builtin.h`` guards them without FP checks:
// skip the update rather than propagate an infinity at the singular point.
template <typename T> inline void wp_adj_log2(T x, thread T& ax, T r) {
    ax += (T(1) / x) * (T(1) / metal::log(T(2))) * r;
}
template <typename T> inline void wp_adj_log10(T x, thread T& ax, T r) {
    ax += (T(1) / x) * (T(1) / metal::log(T(10))) * r;
}
template <typename T> inline void wp_adj_pow(T a, T b, T ret, thread T& aa, thread T& ab, T r) {
    aa += b * metal::pow(a, b - T(1)) * r;
    ab += metal::log(a) * ret * r;
}
template <typename T> inline void wp_adj_tan(T x, thread T& ax, T r) {
    T c = metal::cos(x);
    if (c != T(0)) ax += (T(1) / (c * c)) * r;
}
template <typename T> inline void wp_adj_asin(T x, thread T& ax, T r) {
    T d = metal::sqrt(T(1) - x * x);
    if (d > T(0)) ax += (T(1) / d) * r;
}
template <typename T> inline void wp_adj_acos(T x, thread T& ax, T r) {
    T d = metal::sqrt(T(1) - x * x);
    if (d > T(0)) ax -= (T(1) / d) * r;
}
template <typename T> inline void wp_adj_atan(T x, thread T& ax, T r) { ax += r / (x * x + T(1)); }
template <typename T> inline void wp_adj_atan2(T y, T x, thread T& ay, thread T& ax, T r) {
    T d = x * x + y * y;
    if (d > T(0)) { ax -= (y / d) * r; ay += (x / d) * r; }
}
template <typename T> inline void wp_adj_sinh(T x, thread T& ax, T r) { ax += metal::cosh(x) * r; }
template <typename T> inline void wp_adj_cosh(T x, thread T& ax, T r) { ax += metal::sinh(x) * r; }
template <typename T> inline void wp_adj_lerp(T a, T b, T t, thread T& aa, thread T& ab, thread T& at, T r) {
    aa += r * (T(1) - t);
    ab += r * t;
    at += b * r - a * r;
}
template <typename T>
inline void wp_adj_smoothstep(T e0, T e1, T x, thread T& ae0, thread T& ae1, thread T& ax, T r) {
    T ab = e0 - e1;
    T a_x = e0 - x;
    T bx = e1 - x;
    T xb = x - e1;
    if (bx / ab >= T(0) || a_x / ab <= T(0)) return;
    T ab3 = ab * ab * ab;
    T ab4 = ab3 * ab;
    ae0 += r * ((T(6) * a_x * bx * bx) / ab4);
    ae1 += r * ((T(6) * a_x * a_x * xb) / ab4);
    ax += r * ((T(6) * a_x * bx) / ab3);
}
// ``wp.float32(x)`` / ``wp.int32(x)`` style casts. Warp emits
// ``adj_<type>(x, adj_x, adj_ret)``; integer results carry no gradient.
template <typename T, typename U> inline void wp_adj_cast(T x, thread T& ax, U r) { ax += T(r); }
template <typename T, typename U> inline void wp_adj_cast_nodiff(T x, thread T& ax, U r) { }
// Gradient accumulation into a ``device`` buffer. Several threads can hold
// the adjoint of the same array element (any kernel where more than one
// lane reads ``arr[i]``), so this must be atomic. The pointer cast is
// legal MSL and verified to give the right total under contention.
inline void wp_adj_accum(device float* p, float v) {
    atomic_fetch_add_explicit((device atomic_float*)p, v, memory_order_relaxed);
}
// MSL has no 16-bit atomics: accumulate a half through a compare-exchange
// loop on the aligned 32-bit word that contains it. Each lane's CAS is
// independent (no lock is held), so divergent retries make progress.
inline void wp_adj_accum(device half* p, half v) {
    const ulong addr = (ulong)p;
    device atomic_uint* w = (device atomic_uint*)(addr & ~(ulong)3);
    const bool hi = (addr & 2) != 0;
    uint old = atomic_load_explicit(w, memory_order_relaxed);
    while (true) {
        const ushort bits = hi ? (ushort)(old >> 16) : (ushort)(old & 0xFFFFu);
        const half cur = as_type<half>(bits);
        const ushort nb = as_type<ushort>((half)(cur + v));
        const uint nw = hi ? ((old & 0x0000FFFFu) | ((uint)nb << 16)) : ((old & 0xFFFF0000u) | (uint)nb);
        if (atomic_compare_exchange_weak_explicit(w, &old, nw, memory_order_relaxed, memory_order_relaxed)) break;
    }
}
"""

# Per-vector-length adjoint helpers: component constructors, dot/length/
# normalize, and the mixed vec*scalar products. Emitted only for the
# lengths a kernel actually uses so the generated source stays readable.
_ADJ_VEC_HELPER_LENGTHS = (2, 3, 4)


def _adj_vec_helpers(n: int, scalar: str = "float") -> str:
    """MSL adjoint helpers for the native ``floatN`` / ``halfN`` vector types."""
    sc = scalar
    v = f"{sc}{n}"
    comps = "".join(f"    a{i} += r[{i}];\n" for i in range(n))
    args = ", ".join(f"{sc} c{i}" for i in range(n))
    refs = ", ".join(f"thread {sc}& a{i}" for i in range(n))
    # ``wp.vec2(s)`` broadcasts one scalar into every component, so its
    # adjoint sums the whole gradient back into that scalar.
    bcast = " + ".join(f"r[{i}]" for i in range(n))
    zero = f"({sc})0"
    two = f"({sc})2"
    return (
        f"inline void wp_adj_vec_t({args}, {refs}, {v} r) {{\n{comps}}}\n"
        f"inline void wp_adj_vec_t({sc} c, thread {sc}& a, {v} r) {{ a += {bcast}; }}\n"
        # Copy / element-cast constructor (``wp.vec2(other)``), which
        # warp.fem's dispatch kernels emit when narrowing an accumulator.
        # Same-length, so the adjoint is a straight accumulation.
        f"inline void wp_adj_vec_t({v} other, thread {v}& adj_other, {v} r) {{ adj_other += r; }}\n"
        f"inline void wp_adj_mul({v} a, {sc} b, thread {v}& aa, thread {sc}& ab, {v} r) {{\n"
        f"    aa += b * r;\n    ab += metal::dot(a, r);\n}}\n"
        f"inline void wp_adj_mul({sc} a, {v} b, thread {sc}& aa, thread {v}& ab, {v} r) {{\n"
        f"    aa += metal::dot(b, r);\n    ab += a * r;\n}}\n"
        f"inline void wp_adj_div({v} a, {sc} b, {v} ret, thread {v}& aa, thread {sc}& ab, {v} r) {{\n"
        f"    aa += r / b;\n    ab -= metal::dot(r, ret) / b;\n}}\n"
        # 5-arg forms (no ``ret``) that Warp's IR emits for vec/scalar and
        # scalar/vec division (warp/native/vec.h).
        f"inline void wp_adj_div({v} a, {sc} s, thread {v}& aa, thread {sc}& as, {v} r) {{\n"
        f"    as -= metal::dot(a, r) / (s * s);\n    aa += r / s;\n}}\n"
        f"inline void wp_adj_div({sc} s, {v} a, thread {sc}& as, thread {v}& aa, {v} r) {{\n"
        f"    for (int i = 0; i < {n}; ++i) {{ {sc} inv = ({sc})1 / a[i]; aa[i] -= s * r[i] * inv * inv; "
        f"as += r[i] * inv; }}\n}}\n"
        f"inline void wp_adj_dot({v} a, {v} b, thread {v}& aa, thread {v}& ab, {sc} r) {{\n"
        f"    aa += b * r;\n    ab += a * r;\n}}\n"
        f"inline void wp_adj_length({v} a, {sc} ret, thread {v}& aa, {sc} r) {{\n"
        f"    if (ret > {zero}) aa += a * (r / ret);\n}}\n"
        f"inline void wp_adj_length_sq({v} a, thread {v}& aa, {sc} r) {{ aa += a * ({two} * r); }}\n"
        f"inline void wp_adj_normalize({v} a, {v} ret, thread {v}& aa, {v} r) {{\n"
        f"    {sc} d = metal::length(a);\n"
        f"    if (d > {zero}) aa += (r - ret * metal::dot(ret, r)) / d;\n}}\n"
        # ``wp.extract(v, i)`` on a vector: scatter the scalar adjoint back
        # into the indexed component. The index itself is non-differentiable.
        f"inline void wp_adj_extract({v} a, int i, thread {v}& aa, thread int& ai, {sc} r) {{\n"
        f"    aa[i] += r;\n}}\n"
        # Component-wise products. MSL's ``*`` on vectors is already
        # component-wise, so these mirror the scalar rules per lane.
        f"inline void wp_adj_cw_mul({v} a, {v} b, thread {v}& aa, thread {v}& ab, {v} r) {{\n"
        f"    aa += b * r;\n    ab += a * r;\n}}\n"
        f"inline void wp_adj_cw_div({v} a, {v} b, {v} ret, thread {v}& aa, thread {v}& ab, {v} r) {{\n"
        f"    aa += r / b;\n    ab -= r * ret / b;\n}}\n"
    )


def _adj_int_vec_helpers(n: int, scalar: str) -> str:
    """Adjoint helpers for the integer vector types (``int2``, ``uint3``, ...).

    Integer values carry no gradient, but Warp's reverse pass still emits
    ``adj_extract`` / ``adj_vec_t`` for them (warp.fem indexes a ``vec2i``
    grid resolution this way). The CPU backend accumulates into the integer
    dual and then discards it, so mirror that rather than dropping the
    statement — a dropped statement would leave an undeclared identifier if
    the dual is read later.
    """
    v = f"{scalar}{n}"
    comps = "".join(f"    a{i} += r[{i}];\n" for i in range(n))
    args = ", ".join(f"{scalar} c{i}" for i in range(n))
    refs = ", ".join(f"thread {scalar}& a{i}" for i in range(n))
    bcast = " + ".join(f"r[{i}]" for i in range(n))
    return (
        f"inline void wp_adj_vec_t({args}, {refs}, {v} r) {{\n{comps}}}\n"
        f"inline void wp_adj_vec_t({scalar} c, thread {scalar}& a, {v} r) {{ a += {bcast}; }}\n"
        f"inline void wp_adj_extract({v} a, int i, thread {v}& aa, thread int& ai, {scalar} r) {{\n"
        f"    aa[i] += r;\n}}\n"
    )


def _adj_mat_helpers(n: int) -> str:
    """MSL adjoint helpers for the native square ``floatNxN`` matrix type.

    Native MSL matrices are column-major (``m[col][row]``) while Warp's IR is
    row-major, so a logical element ``(i, j)`` is ``m[j][i]`` here. Products,
    ``metal::transpose`` and ``metal::determinant`` are layout-agnostic — they
    operate on the same logical matrix — so the formulas below match
    ``warp/native/mat.h`` directly; only the explicit element indices swap.

    Concrete overloads matter beyond convenience: the generic scalar
    ``wp_adj_mul`` template would otherwise deduce ``T = floatNxN`` and
    compute ``aa += b * r``, which compiles but is the wrong adjoint for a
    matrix product.
    """
    m = f"float{n}x{n}"
    v = f"float{n}"
    diag = "".join(f"    am[{i}][{i}] += r;\n" for i in range(n))
    diag_get = "".join(f"    ad[{i}] += r[{i}][{i}];\n" for i in range(n))
    diag_put = "".join(f"    am[{i}][{i}] += r[{i}];\n" for i in range(n))
    cw = "".join(f"    aa[{i}] += b[{i}] * r[{i}];\n    ab[{i}] += a[{i}] * r[{i}];\n" for i in range(n))
    cw_div = "".join(f"    aa[{i}] += r[{i}] / b[{i}];\n    ab[{i}] -= r[{i}] * ret[{i}] / b[{i}];\n" for i in range(n))
    # ``outer(u, w)`` is logical ``u wᵀ``; in column-major storage its column
    # j is ``u * w[j]``.
    outer_rb = ", ".join(f"r * b[{i}]" for i in range(n))
    outer_br = ", ".join(f"b * r[{i}]" for i in range(n))
    ddot = " + ".join(f"metal::dot(a[{i}], r[{i}])" for i in range(n))
    ddot_ret = " + ".join(f"metal::dot(ret[{i}], r[{i}])" for i in range(n))
    if n == 2:
        det_body = (
            "    am[0][0] += m[1][1] * r;\n"
            "    am[1][1] += m[0][0] * r;\n"
            "    am[1][0] -= m[0][1] * r;\n"
            "    am[0][1] -= m[1][0] * r;\n"
        )
    else:
        # Cofactor expansion: d(det)/d(i,j) = (-1)^(i+j) * det(minor(i, j)).
        # Written as a loop so 3x3 and 4x4 share one obviously-correct form.
        det_body = (
            f"    for (int i = 0; i < {n}; ++i) for (int j = 0; j < {n}; ++j) {{\n"
            f"        float{n - 1}x{n - 1} sub;\n"
            f"        int rr = 0;\n"
            f"        for (int a = 0; a < {n}; ++a) {{\n"
            f"            if (a == i) continue;\n"
            f"            int cc = 0;\n"
            f"            for (int b = 0; b < {n}; ++b) {{\n"
            f"                if (b == j) continue;\n"
            f"                sub[cc][rr] = m[b][a];\n"
            f"                ++cc;\n"
            f"            }}\n"
            f"            ++rr;\n"
            f"        }}\n"
            f"        float sgn = ((i + j) % 2 == 0) ? 1.0f : -1.0f;\n"
            f"        am[j][i] += sgn * metal::determinant(sub) * r;\n"
            f"    }}\n"
        )
    return (
        f"inline void wp_adj_mul({m} a, {m} b, thread {m}& aa, thread {m}& ab, {m} r) {{\n"
        f"    aa += r * metal::transpose(b);\n    ab += metal::transpose(a) * r;\n}}\n"
        f"inline void wp_adj_mul({m} a, {v} b, thread {m}& aa, thread {v}& ab, {v} r) {{\n"
        f"    aa += {m}({outer_rb});\n    ab += metal::transpose(a) * r;\n}}\n"
        f"inline void wp_adj_mul({v} b, {m} a, thread {v}& ab, thread {m}& aa, {v} r) {{\n"
        f"    aa += {m}({outer_br});\n    ab += r * metal::transpose(a);\n}}\n"
        f"inline void wp_adj_mul({m} a, float b, thread {m}& aa, thread float& ab, {m} r) {{\n"
        f"    aa += b * r;\n    ab += {ddot};\n}}\n"
        f"inline void wp_adj_mul(float b, {m} a, thread float& ab, thread {m}& aa, {m} r) {{\n"
        f"    aa += b * r;\n    ab += {ddot};\n}}\n"
        f"inline void wp_adj_div({m} a, float b, {m} ret, thread {m}& aa, thread float& ab, {m} r) {{\n"
        f"    aa += r / b;\n    ab -= ({ddot_ret}) / b;\n}}\n"
        # 5-arg forms (no ``ret``), warp/native/mat.h.
        f"inline void wp_adj_div({m} a, float s, thread {m}& aa, thread float& as, {m} r) {{\n"
        f"    as -= ({ddot}) / (s * s);\n    aa += r / s;\n}}\n"
        f"inline void wp_adj_div(float s, {m} a, thread float& as, thread {m}& aa, {m} r) {{\n"
        f"    for (int i = 0; i < {n}; ++i) for (int j = 0; j < {n}; ++j) {{ float inv = 1.0f / a[j][i]; "
        f"aa[j][i] -= s * r[j][i] * inv * inv; as += r[j][i] * inv; }}\n}}\n"
        f"inline void wp_adj_ddot({m} a, {m} b, thread {m}& aa, thread {m}& ab, float r) {{\n"
        f"    aa += b * r;\n    ab += a * r;\n}}\n"
        f"inline void wp_adj_cw_mul({m} a, {m} b, thread {m}& aa, thread {m}& ab, {m} r) {{\n{cw}}}\n"
        f"inline void wp_adj_cw_div({m} a, {m} b, {m} ret, thread {m}& aa, thread {m}& ab, {m} r) {{\n{cw_div}}}\n"
        f"inline void wp_adj_transpose({m} a, thread {m}& aa, {m} r) {{ aa += metal::transpose(r); }}\n"
        f"inline void wp_adj_trace({m} m, thread {m}& am, float r) {{\n{diag}}}\n"
        f"inline void wp_adj_diag({v} d, thread {v}& ad, {m} r) {{\n{diag_get}}}\n"
        f"inline void wp_adj_get_diag({m} m, thread {m}& am, {v} r) {{\n{diag_put}}}\n"
        f"inline void wp_adj_outer({v} a, {v} b, thread {v}& aa, thread {v}& ab, {m} r) {{\n"
        f"    aa += r * b;\n    ab += metal::transpose(r) * a;\n}}\n"
        # ``wp.extract(m, i, j)`` — logical (i, j) is ``m[j][i]`` here.
        f"inline void wp_adj_extract({m} m, int i, int j, thread {m}& am, "
        f"thread int& ai, thread int& aj, float r) {{\n    am[j][i] += r;\n}}\n"
        # Row extract: ``wp.extract(m, i)`` yields logical row i, whose
        # components live one per column.
        f"inline void wp_adj_extract({m} m, int i, thread {m}& am, thread int& ai, {v} r) {{\n"
        f"    for (int j = 0; j < {n}; ++j) am[j][i] += r[j];\n}}\n"
        f"inline void wp_adj_determinant({m} m, thread {m}& am, float r) {{\n{det_body}}}\n"
        # d(inv)/dM, see Giles, "An extended collection of matrix derivative
        # results for forward and reverse mode AD", 2.2.3.
        f"inline void wp_adj_inverse({m} m, {m} ret, thread {m}& am, {m} r) {{\n"
        f"    {m} invt = metal::transpose(ret);\n    am -= invt * r * invt;\n}}\n"
        f"inline void wp_adj_matrix_from_cols({', '.join(f'{v} c{i}' for i in range(n))}, "
        f"{', '.join(f'thread {v}& ac{i}' for i in range(n))}, {m} r) {{\n"
        + "".join(f"    ac{i} += r[{i}];\n" for i in range(n))
        + "}\n"
        f"inline void wp_adj_matrix_from_rows({', '.join(f'{v} c{i}' for i in range(n))}, "
        f"{', '.join(f'thread {v}& ac{i}' for i in range(n))}, {m} r) {{\n"
        f"    {m} rt = metal::transpose(r);\n" + "".join(f"    ac{i} += rt[{i}];\n" for i in range(n)) + "}\n"
    )


_ADJ_VEC3_EXTRA = """\
inline void wp_adj_cross(float3 a, float3 b, thread float3& aa, thread float3& ab, float3 r) {
    aa += metal::cross(b, r);
    ab += metal::cross(r, a);
}
"""

# ``wp::adj_<name>`` -> ``wp_adj_<name>`` for everything the helper block
# above defines. Anything absent stays as ``wp::adj_*`` and trips
