    (re.compile(r"\bwp::mesh_query_point_sign_winding_number\b"), "wp_mesh_query_point_sign_winding_number"),
    (re.compile(r"\bwp::mesh_query_winding_number\b"), "wp_mesh_query_winding_number"),
